let state; try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch(e){state=seed()}
state.seaBookings=state.seaBookings||[];state.cheques=state.cheques||[];state.payments=state.payments||[];
let ui={page:'dashboard',jobId:state.jobs[0].id,tab:'details',filter:'',status:'All',modal:'',invId:'',role:state.role||'Management',view:'',dateFrom:'',dateTo:'',reportGroup:'Customer',period:'All time',ledgerTab:'General ledger'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast('Browser storage is full; export data to back it up.')}}
function audit(action,module){state.audit.unshift({date:new Date().toLocaleString('en-IN'),user:ui.role+' (demo)',action,module});state.audit=state.audit.slice(0,100);save()}
function toast(msg){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}t.textContent=msg;clearTimeout(window.__t);window.__t=setTimeout(()=>t.remove(),4400)}
function allowed(area){return ui.role==='Management'||(ui.role==='Finance'&&['finance','ledger','payables','reports','tasks','customers'].includes(area))||(ui.role==='Sales'&&['jobs','quotes','customers','tasks','bookings','sea'].includes(area))||(ui.role==='Operations'&&['jobs','documents','bookings','sea','stock','customers','tasks'].includes(area))||(ui.role==='Documentation'&&['documents','jobs','bookings','sea','tasks'].includes(area))}
function canFinance(){return ['Management','Finance'].includes(ui.role)}
function canProfit(){return ui.role==='Management'}
function guard(area){if(!allowed(area)){toast('Access restricted for the selected demo role.');return false}return true}
const navGroups=[['WORKSPACE',[['dashboard','▦','Overview'],['jobs','▣','Shipments & Jobs'],['bookings','✈','Airline Bookings'],['sea','⚓','Sea Freight Docs'],['documents','▤','Document Centre']]],['COMMERCIAL',[['quotes','◈','Quotes & Tariffs'],['stock','▥','AWB Stock & Allocation']]],['FINANCE',[['finance','▧','Invoices & Receivables'],['payables','⇄','Accounts Payable'],['ledger','▤','Ledger & Bank'],['partners','◎','Profit & Partner Sharing']]],['CONTROL',[['tasks','☑','Follow-ups & Reminders'],['reports','▥','Reports & Insights'],['customers','♙','Customers & Vendors'],['settings','⚙','Settings & Audit']]]];
const names={dashboard:'Overview',jobs:'Shipments & Jobs',bookings:'Airline Bookings',sea:'Sea Freight Docs',ledger:'Ledger & Bank',documents:'Document Centre',quotes:'Quotes & Tariffs',stock:'AWB Stock & Allocation',finance:'Invoices & Receivables',payables:'Accounts Payable',partners:'Profit & Partner Sharing',tasks:'Follow-ups & Reminders',reports:'Reports & Insights',customers:'Customers & Vendors',settings:'Settings & Audit',job:'Shipment Workspace',newjob:'New Shipment',invoiceform:'Invoice Editor',invoiceview:'Invoice Preview'};
function navigate(page,props={}){ui.page=page;Object.assign(ui,props);window.scrollTo(0,0);render()}
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-logo">A↗</div><div><strong>AirBridge</strong><span>FREIGHT WORKSPACE</span></div></div>${navGroups.map(([group,navs])=>`<div class="navcap">${group}</div>${navs.map(([key,ico,label])=>`<button class="navitem ${ui.page===key||((ui.page==='job'||ui.page==='newjob')&&key==='jobs')||((ui.page==='invoiceform'||ui.page==='invoiceview')&&key==='finance')?'active':''}" onclick="go('${key}')"><span class="navico">${ico}</span><span class="navtext">${label}</span>${key==='tasks'&&state.tasks.filter(t=>!t.done).length?`<span class="num">${state.tasks.filter(t=>!t.done).length}</span>`:''}</button>`).join('')}`).join('')}<div class="navbottom"><div style="font-weight:750;color:white;margin-bottom:6px">Freight & Logistics Solutions</div><div class="demo">INTERACTIVE PROTOTYPE<br>Local browser data • No live airline or email integrations</div></div></aside>`}
function topbar(){return `<header class="topbar"><span class="breadcrumb">Workspace &nbsp;/&nbsp; <strong>${esc(names[ui.page]||'Overview')}</strong></span><div class="topspacer"></div><div class="top-search"><input id="globalsearch" placeholder="Find job, AWB, customer…" onkeydown="if(event.key==='Enter')globalSearch(this.value)" aria-label="Search across shipments"></div><span class="pilltop">● Demo workspace</span><select class="role" aria-label="Switch role" onchange="setRole(this.value)">${['Management','Sales','Operations','Documentation','Finance'].map(x=>`<option ${x===ui.role?'selected':''}>${x}</option>`).join('')}</select><span class="avatar">${ui.role.slice(0,1)}</span></header>`}
function render(){const page=ui.page;const routes={dashboard:dashboard,jobs:jobs,job:jobView,newjob:newJob,bookings:bookings,sea:sea,ledger:ledger,documents:documents,quotes:quotes,stock:stock,finance:finance,payables:payables,partners:partners,tasks:tasks,reports:reports,customers:customers,settings:settings,invoiceform:invoiceForm,invoiceview:invoiceView};$('#app').innerHTML=`<div class="shell">${sidebar()}<div class="workspace">${topbar()}<div class="noticebar">DEMO MODE — Sample records only. Data stays in this browser. Uploads, email sends, airline confirmations, GST/e-invoice and permissions are simulated or local only.</div><main class="page">${(page!=='dashboard'&&!allowed(({job:'jobs',newjob:'jobs',invoiceform:'finance',invoiceview:'finance'})[page]||page))?noAccess():(routes[page]||dashboard)()}<div class="footerhint">AirBridge prototype v1.0 · Cross-module demo workflows · Not a production financial or airline system</div></main></div></div>${ui.modal?modal():''}`}
function head(title,sub,acts=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${acts}</div></div>`}
function badge(s){const v=(s||'').toLowerCase();let c=/paid$|delivered|confirmed|approved|accepted|active|complete/.test(v)?'good':/overdue|rejected|cancelled|urgent/.test(v)?'danger':/pending|part paid|waitlist|requested|draft|in transit|booked/.test(v)?'warn':'info';return `<span class="badge ${c}">${esc(s||'—')}</span>`}
function totals(j){const cost=(j.costs||[]).reduce((a,b,i)=>a+(+b||0)*((j.costFx||[])[i]||1),0);const sell=(+j.sell||0)*(+j.fx||1),profit=sell-cost;return {cost,sell,profit,margin:sell?profit/sell*100:0}}
function invTotal(inv){const sub=inv.lines.reduce((s,x)=>s+(+x.qty||0)*(+x.rate||0),0),gst=inv.lines.reduce((s,x)=>s+(+x.qty||0)*(+x.rate||0)*(+x.gst||0)/100,0);return {sub,gst,total:sub+gst,balance:Math.max(0,sub+gst-(+inv.paid||0))}}
const field=(label,name,value='',type='text',opts={})=>`<div class="field ${opts.w||''}"><label for="${name}">${label}${opts.req?' *':''}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${opts.req?'required':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.extra||''}></div>`;
const select=(label,name,value,list,opts={})=>`<div class="field ${opts.w||''}"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${opts.extra||''}>${list.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`;
const textArea=(label,name,val='',opts={})=>`<div class="field ${opts.w||'w4'}"><label for="${name}">${label}</label><textarea id="${name}" name="${name}">${esc(val)}</textarea></div>`;
const cbtn=(text,action='')=>`<button class="btn" onclick="${action}">${text}</button>`;
function noAccess(){return `<div class="card cardpad"><h3>Restricted access</h3><p class="muted">The selected role cannot view sensitive financial details. Switch to Management or Finance to explore these workflows.</p></div>`}
function globalSearch(q){ui.filter=q;navigate('jobs')}
function setRole(v){ui.role=v;state.role=v;save();render()}
function stats(){const t=state.jobs.reduce((a,j)=>{let x=totals(j);a.revenue+=x.sell;a.cost+=x.cost;a.profit+=x.profit;return a},{revenue:0,cost:0,profit:0});let outstanding=state.invoices.filter(i=>i.type==='Tax Invoice').reduce((s,i)=>s+invTotal(i).balance,0);return {...t,outstanding}}
function dashboard(){const s=stats();const roleCan=canFinance();let pending=state.tasks.filter(t=>!t.done);return `${head('Business Overview','All shipment activity, revenue, finance and pending actions in one workspace.',`<button class="btn" onclick="go('reports')">▤ View reports</button><button class="btn primary" onclick="go('newjob')">＋ New shipment</button>`)}<div class="grid four"><div class="metric"><div class="mlabel">Total shipments <span>▣</span></div><div class="mval">${state.jobs.length}</div><div class="mfoot">${state.jobs.filter(j=>j.status!=='Delivered').length} actively being handled</div></div><div class="metric"><div class="mlabel">Shipment revenue <span>↗</span></div><div class="mval">${roleCan?money(s.revenue):'Restricted'}</div><div class="mfoot">Demo period · INR equivalent</div></div><div class="metric"><div class="mlabel">Gross profit <span>◫</span></div><div class="mval">${canProfit()?money(s.profit):'Restricted'}</div><div class="mfoot">${canProfit()?(s.revenue?s.profit/s.revenue*100:0).toFixed(1)+'% margin':'Management access required'}</div></div><div class="metric"><div class="mlabel">Unpaid receivables <span>↻</span></div><div class="mval">${roleCan?money(s.outstanding):'Restricted'}</div><div class="mfoot">Invoices awaiting full payment</div></div></div><div class="grid two section"><section class="card cardpad"><div class="cardtitle"><h3>Shipment status</h3><button class="btn link" onclick="go('jobs')">View all shipments →</button></div>${['Booked','Documents pending','In transit','Delivered'].map(k=>{let n=state.jobs.filter(j=>j.status===k).length;return `<div class="minirow"><div>${badge(k)}</div><div style="display:flex;gap:13px;align-items:center;width:45%"><div class="progress" style="width:100%"><span style="width:${state.jobs.length?n/state.jobs.length*100:0}%"></span></div><strong>${n}</strong></div></div>`}).join('')}<div class="note" style="margin-top:15px">Shipment details, costs, AWBs, uploaded documents, bookings and invoices are all connected through the unique Job ID.</div></section><section class="card cardpad"><div class="cardtitle"><h3>Pending actions</h3><button class="btn link" onclick="go('tasks')">Open task centre →</button></div>${pending.slice(0,4).map(t=>`<div class="minirow"><div><div style="font-weight:700;margin-bottom:5px">${esc(t.title)}</div><small class="muted">${esc(t.owner)} · Due ${fmtDate(t.due)}</small></div>${badge(t.due<TODAY?'Overdue':t.priority)}</div>`).join('')||'<p class="muted">No tasks pending.</p>'}<button class="btn small" style="margin-top:13px" onclick="openModal('task')">＋ Add follow-up</button></section></div><div class="grid two section"><section class="card cardpad"><div class="cardtitle"><h3>Recent shipments</h3><button class="btn link" onclick="go('jobs')">See all →</button></div><div class="tablebox"><table class="table"><thead><tr><th>Job ID</th><th>Customer</th><th>Lane</th><th>Status</th></tr></thead><tbody>${state.jobs.slice(-4).reverse().map(j=>`<tr><td><button class="linkbutton" onclick="openJob('${j.id}')">${j.id}</button></td><td>${esc(j.customer)}</td><td>${j.origin} → ${j.destination}</td><td>${badge(j.status)}</td></tr>`).join('')}</tbody></table></div></section><section class="card cardpad"><div class="cardtitle"><h3>Quick access</h3><small>Common everyday tasks</small></div><div class="grid two" style="gap:10px">${[['＋','New shipment','go(\'newjob\')'],['✈','Flight booking','go(\'bookings\')'],['⇧','Upload AWB / docs','go(\'documents\')'],['▧','Create an invoice','newInvoice()'],['◈','New quotation','openModal(\'quote\')'],['☑','Payment follow-up','openModal(\'task\')']].map(([ic,l,ac])=>`<button class="btn" style="padding:17px 11px;justify-content:flex-start" onclick="${ac}"><span style="font-size:18px;color:var(--blue)">${ic}</span> ${l}</button>`).join('')}</div></section></div>`}
function jobs(){let arr=state.jobs.filter(j=>[j.id,j.customer,j.shipper,j.consignee,j.mawb,j.hawb,j.origin,j.destination,j.airline].join(' ').toLowerCase().includes(ui.filter.toLowerCase())&&(ui.status==='All'||j.status===ui.status));return `${head('Shipments & Jobs','Search and manage every forwarding job from enquiry through delivery and billing.',`<button class="btn" onclick="csv('jobs')">⇩ Export Excel-ready CSV</button><button class="btn primary" onclick="go('newjob')">＋ Create shipment</button>`)}<div class="card cardpad"><div class="filters"><input placeholder="Search Job ID, MAWB, HAWB, customer…" value="${esc(ui.filter)}" oninput="ui.filter=this.value;refreshList()" id="listfilter"><select onchange="ui.status=this.value;render()">${['All','Booked','Documents pending','In transit','Delivered','Cancelled','Draft'].map(s=>`<option ${ui.status===s?'selected':''}>${s}</option>`).join('')}</select><span class="muted">${arr.length} records</span></div><div class="tablebox"><table class="table"><thead><tr><th>Job ID</th><th>Customer / Shipper</th><th>Route</th><th>AWB / HAWB</th><th>Airline</th><th>Pieces / Chargeable</th><th>Flight date</th><th>Owner</th><th>Status</th>${canProfit()?'<th>Margin</th>':''}</tr></thead><tbody id="jobrows">${jobRows(arr)}</tbody></table></div></div>`}
function jobRows(arr){return arr.map(j=>`<tr><td><button class="linkbutton" onclick="openJob('${j.id}')">${esc(j.id)}</button></td><td><strong>${esc(j.customer)}</strong><div class="muted smalltxt">${esc(j.shipper)}</div></td><td>${esc(j.origin)} → ${esc(j.destination)}</td><td><span class="mononum">${esc(j.mawb||'Pending')}</span><div class="muted smalltxt">${esc(j.hawb||'—')}</div></td><td>${esc(j.airline)}</td><td>${j.pieces} / ${j.chargeable} kg</td><td>${fmtDate(j.date)}</td><td>${esc(j.owner)}</td><td>${badge(j.status)}</td>${canProfit()?`<td style="font-weight:700">${totals(j).margin.toFixed(1)}%</td>`:''}</tr>`).join('')||'<tr><td colspan="11" class="empty">No shipments match your filters.</td></tr>'}
function refreshList(){let arr=state.jobs.filter(j=>[j.id,j.customer,j.shipper,j.consignee,j.mawb,j.hawb,j.origin,j.destination,j.airline].join(' ').toLowerCase().includes(ui.filter.toLowerCase())&&(ui.status==='All'||j.status===ui.status));if($('#jobrows'))$('#jobrows').innerHTML=jobRows(arr)}
function openJob(jobId,tab='details'){navigate('job',{jobId,tab})}
function getJob(){return state.jobs.find(j=>j.id===ui.jobId)||state.jobs[0]}
function jobView(){const j=getJob(),t=totals(j);const tabs=[['details','Shipment details'],['booking','Flight & AWB'],['docs','Airline documents'],['costs','Rates & costs'],['sharing','Profit sharing'],['billing','Billing & history']];return `${head(j.id,`${esc(j.customer)} · ${esc(j.origin)} → ${esc(j.destination)} · ${esc(j.service)}`,`<button class="btn" onclick="go('jobs')">← All jobs</button><button class="btn" onclick="cloneJob('${j.id}')">Duplicate</button><button class="btn primary" onclick="saveJob('${j.id}')">✓ Save changes</button>`)}<div class="grid four" style="margin-bottom:17px"><div class="metric"><div class="mlabel">Status</div><div class="mval" style="font-size:16px;margin-top:16px">${badge(j.status)}</div></div><div class="metric"><div class="mlabel">MAWB</div><div class="mval" style="font-size:20px">${esc(j.mawb||'Not assigned')}</div></div><div class="metric"><div class="mlabel">Chargeable weight</div><div class="mval" style="font-size:21px">${j.chargeable} kg</div></div><div class="metric"><div class="mlabel">${canProfit()?'Gross margin':'Assigned owner'}</div><div class="mval" style="font-size:21px">${canProfit()?t.margin.toFixed(1)+'%':esc(j.owner)}</div></div></div><div class="card cardpad"><div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${ui.tab===k?'active':''}" onclick="ui.tab='${k}';render()">${l}</button>`).join('')}</div>${({details:()=>jobDetails(j),booking:()=>jobBooking(j),docs:()=>jobDocs(j),costs:()=>jobCosts(j),sharing:()=>jobSharing(j),billing:()=>jobBilling(j)})[ui.tab]?.()||jobDetails(j)}</div>`}
function jobDetails(j){return `<div class="subhead">Consignment and routing</div><div class="formgrid">${field('Customer / Billing party','j_customer',j.customer)}${field('Shipper','j_shipper',j.shipper)}${field('Consignee','j_consignee',j.consignee)}${select('Service','j_service',j.service,['Air Export','Air Import','Sea Export','Sea Import','Domestic'])}${field('Origin (IATA)','j_origin',j.origin)}${field('Destination (IATA)','j_destination',j.destination)}${field('Airline','j_airline',j.airline)}${field('Booking agent / GSA','j_agent',j.agent)}${field('Commodity description','j_commodity',j.commodity)}${field('Dimensions / package breakup','j_dimensions',j.dimensions||'','text',{placeholder:'e.g. 10× 80×60×50 cm'})}${field('No. of pieces','j_pieces',j.pieces,'number')}${field('Gross weight (kg)','j_gross',j.gross,'number',{extra:'step="0.01" oninput="chargeableCalc()"'})}${field('Volume (CBM)','j_volume',j.volume,'number',{extra:'step="0.01" oninput="chargeableCalc()"'})}${field('Chargeable weight (kg)','j_chargeable',j.chargeable,'number',{extra:'step="0.01"'})}${field('Flight number(s)','j_flight',j.flight)}${field('Shipment / flight date','j_date',j.date,'date')}${field('Lane / project code','j_lane',j.lane)}${select('Status','j_status',j.status,['Draft','Booked','Documents pending','Accepted','In transit','Delivered','Cancelled'])}${select('Assigned to','j_owner',j.owner,TEAM)}${field('Other assigned team members','j_assignees',(j.assignees||[]).join(', '),'text',{placeholder:'Comma-separated names'})}${select('Priority','j_priority',j.priority||'Normal',['Low','Normal','High','Urgent'])}${select('Branch','j_branch',j.branch,['Delhi (DEL)','Mumbai (BOM)','Bengaluru (BLR)','Hyderabad (HYD)'])}${select('Security screening','j_screening',j.screening,['Not required','Required','Pending','Accepted','Rejected'])}${textArea('Handling notes / special instructions','j_notes',j.notes,{w:'w4'})}</div><div class="note" style="margin-top:18px">Volume-weight estimate is CBM × 166.67 kg (common air-cargo approximation). The chargeable weight is editable because airline-specific rules may differ.</div>`}
function chargeableCalc(){let v=+$('input[name=j_volume]')?.value||0,g=+$('input[name=j_gross]')?.value||0;if($('input[name=j_chargeable]'))$('input[name=j_chargeable]').value=Math.ceil(Math.max(v*166.67,g))}
function saveJob(jobId){let j=state.jobs.find(x=>x.id===jobId);if(!j)return;const form=$('.formgrid');if(!form){toast('Open a shipment tab with editable fields first.');return}if(ui.tab==='details'){for(const k of ['customer','shipper','consignee','service','origin','destination','airline','agent','commodity','dimensions','assignees','priority','pieces','gross','volume','chargeable','flight','date','lane','status','owner','branch','screening','notes']){let el=$('[name=j_'+k+']');if(el)j[k]=k==='assignees'?el.value.split(',').map(x=>x.trim()).filter(Boolean):['pieces','gross','volume','chargeable'].includes(k)?+el.value:el.value}audit('Updated shipment '+j.id,'Shipments');toast('Shipment saved in this browser.')}else if(ui.tab==='booking'){for(const k of ['mawb','hawb','flight','date','allotment','screening']){let el=$('[name=b_'+k+']');if(el)j[k]=el.value}j.awbMeta=j.awbMeta||{};for(const k of ['shipperAcct','consigneeAcct','iataCode','payMode','declaredCarriage','declaredCustoms','insurance','shc','handling','rateClass']){let el=$('[name=b_'+k+']');if(el)j.awbMeta[k]=el.value}audit('Updated AWB / route '+j.id,'Booking');toast('Booking and AWB details saved.')}else if(ui.tab==='costs'){if(!canFinance()){toast('Financial edit restricted.');return}j.sell=+$('[name=c_sell]').value||0;j.fx=+$('[name=c_fx]').value||1;j.currency=$('[name=c_currency]').value;j.costs=COST_HEADS.map((x,i)=>+$('[name=c_'+i+']').value||0);j.costCurrencies=COST_HEADS.map((x,i)=>$('[name=c_cur_'+i+']').value);j.costFx=COST_HEADS.map((x,i)=>+$('[name=c_fx_'+i+']').value||1);audit('Changed costs / revenue '+j.id,'Finance');toast('Rates saved; profitability recalculated.')}else{toast('Changes saved on their respective action buttons.');return}save();render()}
function cloneJob(jobId){let old=state.jobs.find(j=>j.id===jobId),j=clone(old);j.id=`JOB-2026-${String(188+state.jobs.length).padStart(4,'0')}`;j.mawb='';j.hawb='';j.status='Draft';state.jobs.unshift(j);audit('Duplicated shipment '+jobId+' into '+j.id,'Shipments');openJob(j.id);toast('Draft duplicated; assign a new MAWB.');}
function newJob(){return `${head('Create new shipment','Create one Job ID and reuse shipment information across documents, booking, billing and profitability.',`<button class="btn" onclick="go('jobs')">Cancel</button>`)}<div class="card cardpad"><div class="steps"><div class="step current"><span class="circle">1</span> Shipment</div><div class="step"><span class="circle">2</span> Booking & AWB</div><div class="step"><span class="circle">3</span> Airline documents</div><div class="step"><span class="circle">4</span> Finance</div></div><form id="newJobForm" onsubmit="createJob(event)"><div class="subhead">Parties & route</div><div class="formgrid">${field('Customer','n_customer','','text',{req:true})}${field('Shipper','n_shipper','','text',{req:true})}${field('Consignee','n_consignee','','text',{req:true})}${select('Service','n_service','Air Export',['Air Export','Air Import','Sea Export','Sea Import','Domestic'])}${field('Origin IATA','n_origin','DEL','text',{req:true})}${field('Destination IATA','n_destination','','text',{req:true})}${field('Airline / carrier','n_airline','','text',{req:true})}${field('GSA / booking agent','n_agent','Direct')}${field('Commodity','n_commodity','','text',{req:true})}${field('Dimensions / package breakup','n_dimensions','','text',{placeholder:'Package dimensions in cm'})}${field('Pieces','n_pieces',1,'number',{req:true,extra:'min="1"'})}${field('Gross weight (kg)','n_gross',0,'number',{extra:'step="0.01"'})}${field('Volume (CBM)','n_volume',0,'number',{extra:'step="0.01"'})}${field('Flight number','n_flight','')}${field('Flight date','n_date',TODAY,'date')}${select('Assigned operator','n_owner',TEAM[0],TEAM)}${field('Project / Lane name','n_project','')}${textArea('Special handling remarks','n_notes','')}</div><div class="formactions"><button class="btn primary" type="submit">Create job & continue →</button></div></form></div>`}
function createJob(e){e.preventDefault();const v=n=>document.getElementsByName('n_'+n)[0]?.value||'';const jid=`JOB-2026-${String(188+state.jobs.length).padStart(4,'0')}`;const origin=v('origin').toUpperCase(),destination=v('destination').toUpperCase(),gross=+v('gross'),volume=+v('volume');const j={id:jid,customer:v('customer'),shipper:v('shipper'),consignee:v('consignee'),origin,destination,airline:v('airline'),agent:v('agent'),mawb:'',hawb:'',flight:v('flight'),date:v('date'),commodity:v('commodity'),dimensions:v('dimensions'),assignees:[],priority:'Normal',pieces:+v('pieces'),gross,volume,chargeable:Math.ceil(Math.max(gross,volume*166.67)),currency:'INR',fx:1,sell:0,costs:Array(8).fill(0),status:'Draft',owner:v('owner'),branch:state.settings.branch,lane:v('project')||origin+'–'+destination,notes:v('notes'),screening:'Pending',allotment:'General',service:v('service'),created:TODAY};state.jobs.unshift(j);audit('Created new shipment '+jid,'Shipments');openJob(jid,'booking');toast('Shipment created. Next: enter MAWB, HAWB and flight routing.');}
function jobBooking(j){const b=state.bookings.filter(x=>x.jobId===j.id);return `<div class="subhead">Flight routing and AWB identifiers <button class="btn small" onclick="openModal('booking','${j.id}')">＋ Add flight leg</button></div><div class="formgrid">${field('Master Air Waybill (MAWB)','b_mawb',j.mawb,'text',{placeholder:'123-12345678'})}${field('House Air Waybill (HAWB)','b_hawb',j.hawb)}${field('Flight number(s)','b_flight',j.flight)}${field('Flight / departure date','b_date',j.date,'date')}${select('Allotment type','b_allotment',j.allotment,['General','BSA','Hard block','Soft block','Ad-hoc'])}${select('Screening / airline acceptance','b_screening',j.screening,['Required','Pending','Accepted','Rejected','Not required'])}</div><div class="subhead" style="margin-top:24px">AWB handling & declaration fields</div><div class="formgrid">${field('Shipper account number','b_shipperAcct',j.awbMeta?.shipperAcct||'')}${field('Consignee account number','b_consigneeAcct',j.awbMeta?.consigneeAcct||'')}${field('Issuing agent IATA code','b_iataCode',j.awbMeta?.iataCode||'')}${select('Freight charge terms','b_payMode',j.awbMeta?.payMode||'Prepaid',['Prepaid','Collect','Other'])}${field('Declared value for carriage','b_declaredCarriage',j.awbMeta?.declaredCarriage||'NVD')}${field('Declared value for customs','b_declaredCustoms',j.awbMeta?.declaredCustoms||'NCV')}${field('Insurance amount','b_insurance',j.awbMeta?.insurance||'')}${field('Special handling codes','b_shc',j.awbMeta?.shc||'')}${field('Handling instructions','b_handling',j.awbMeta?.handling||'','text',{w:'w2'})}${select('Rate class','b_rateClass',j.awbMeta?.rateClass||'Q',['Q','N','M','C','R','S'])}</div><div class="subhead" style="margin-top:25px">Flight legs and booking requests</div><div class="tablebox"><table class="table"><thead><tr><th>Booking</th><th>Sector</th><th>Flight</th><th>Departure</th><th>Allotment</th><th>Pieces</th><th>Chargeable kg</th><th>Confirmation</th><th>Action</th></tr></thead><tbody>${b.map(x=>`<tr><td>${x.id}</td><td>${x.origin} → ${x.dest}</td><td>${esc(x.flight)}</td><td>${fmtDate(x.date)}</td><td>${x.allotment}</td><td>${x.pcs}</td><td>${x.weight}</td><td>${badge(x.status)}</td><td><button class="btn small" onclick="setBookingStatus('${x.id}')">Update</button></td></tr>`).join('')||'<tr><td colspan="9" class="muted">No flight legs recorded. Add one above.</td></tr>'}</tbody></table></div><div class="note" style="margin-top:18px">Airline capacity availability, flight schedules and e-AWB transmission are not live in this prototype. Status updates are recorded locally for workflow demonstration.</div>`}
function setBookingStatus(k){let b=state.bookings.find(x=>x.id===k);if(!b)return;let next={Requested:'Confirmed',Confirmed:'Departed',Departed:'Arrived',Arrived:'Delivered',Delivered:'Requested'};b.status=next[b.status]||'Requested';audit('Updated booking '+b.id+' to '+b.status,'Bookings');render();toast('Booking status updated locally; no carrier confirmation sent.')}
function bookings(){return `${head('Airline Bookings','Plan air cargo movements, record MAWB assignment and manage flight legs.',`<button class="btn" onclick="go('stock')">AWB stock</button><button class="btn primary" onclick="openModal('booking')">＋ New booking</button>`)}<div class="grid four"><div class="metric"><div class="mlabel">Open booking requests</div><div class="mval">${state.bookings.filter(b=>b.status==='Requested').length}</div></div><div class="metric"><div class="mlabel">Confirmed bookings</div><div class="mval">${state.bookings.filter(b=>b.status==='Confirmed').length}</div></div><div class="metric"><div class="mlabel">Total chargeable kg</div><div class="mval">${state.bookings.reduce((s,b)=>s+(+b.weight||0),0).toLocaleString('en-IN')}</div></div><div class="metric"><div class="mlabel">AWBs on jobs</div><div class="mval">${state.jobs.filter(j=>j.mawb).length}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Flight and allotment register</h3><small>Manually entered booking information</small></div><div class="tablebox"><table class="table"><thead><tr><th>Booking ID</th><th>Job ID</th><th>Airline</th><th>Route</th><th>Flight / departure</th><th>Type</th><th>Weight</th><th>Status</th><th>Update</th></tr></thead><tbody>${state.bookings.map(b=>{let j=state.jobs.find(x=>x.id===b.jobId);return `<tr><td class="strong">${b.id}</td><td><button class="linkbutton" onclick="openJob('${b.jobId}','booking')">${b.jobId}</button></td><td>${esc(j?.airline||'—')}</td><td>${b.origin} → ${b.dest}</td><td>${esc(b.flight)}<br><small>${fmtDate(b.date)}</small></td><td>${b.allotment}</td><td>${b.weight} kg</td><td>${badge(b.status)}</td><td><button class="btn small" onclick="setBookingStatus('${b.id}')">Next status</button></td></tr>`}).join('')}</tbody></table></div></div><div class="grid three section"><div class="callout"><strong>Booking requests</strong><p class="muted">Link airline, flight, sector, capacity allocation and chargeable weight to a job.</p></div><div class="callout"><strong>AWB stock allocation</strong><p class="muted">Record airline-issued AWB number ranges, station, allocated and remaining numbers.</p></div><div class="callout"><strong>Airline document handoff</strong><p class="muted">Store supporting documentation and create a versioned e-pouch style pack per job.</p></div></div>`}
function jobDocs(j){let ds=state.documents.filter(d=>d.jobId===j.id), types=['MAWB Copy','HAWB Copy','Commercial Invoice','Packing List','Shipping Bill','Rate Confirmation'];return `<div class="subhead">Airline documentation pack <span class="badge info">Upload instead of Print AWB</span></div><div class="note">The requested replacement for SmartKargo's “Print AWB” action is an upload-first airline documentation pack. Upload scanned or digital AWBs, invoices, packing lists and other supporting papers. Actual airline transmission will need an approved integration or delivery channel.</div><div class="grid two section"><div class="sidepanel"><div style="font-weight:750;margin-bottom:12px">Upload documents</div><div class="field"><label>Document category</label><select id="documentType">${DOC_TYPES.map(x=>`<option>${x}</option>`).join('')}</select></div><label class="docdrop" for="docInput" style="display:block;margin-top:13px"><strong>⇧ Select or drop shipment documents</strong><span class="muted">PDF, JPEG, PNG, DOCX, XLSX or other file types</span></label><input id="docInput" type="file" multiple hidden onchange="uploadDocs(event,'${j.id}')"><div class="smalltxt muted" style="margin-top:12px">Files are saved in your browser's local IndexedDB for this demo, not uploaded to a server.</div></div><div class="sidepanel"><div style="font-weight:750;margin-bottom:12px">Airline document checklist</div>${types.map(x=>`<div class="minirow"><span>${esc(x)}</span>${ds.some(d=>d.type===x)?'<span class="badge good">Attached</span>':'<span class="badge warn">Missing</span>'}</div>`).join('')}<div class="formactions"><button class="btn teal" onclick="createAirlinePack('${j.id}')">✓ Prepare airline handoff pack</button></div></div></div><div class="subhead" style="margin-top:25px">Documents and version history</div>${docsTable(ds)}<div class="formactions"><button class="btn" onclick="go('documents')">Open document centre</button><button class="btn" onclick="downloadManifest('${j.id}')">⇩ Download document manifest</button></div>`}
function docsTable(ds){return `<div class="tablebox"><table class="table"><thead><tr><th>Category</th><th>Filename</th><th>Version</th><th>Size</th><th>Uploaded by</th><th>Date</th><th>File</th></tr></thead><tbody>${ds.map(d=>`<tr><td>${esc(d.type)}</td><td class="strong">${esc(d.name)}</td><td>v${d.version}</td><td>${(d.size/1024).toFixed(0)} KB</td><td>${esc(d.by)}</td><td>${esc(d.date)}</td><td><button class="btn small" onclick="downloadFile('${d.blobKey}','${esc(d.name)}')">⇩ Download</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted" style="text-align:center;padding:25px">No files uploaded against this job yet.</td></tr>'}</tbody></table></div>`}
const sessionFiles=new Map();let dbProm=null;function blobDb(){if(!('indexedDB' in window))return Promise.reject(new Error('IndexedDB unavailable'));if(dbProm)return dbProm;dbProm=new Promise((res,rej)=>{const r=indexedDB.open('AirBridgeFileStore',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});return dbProm}
async function storeBlob(k,file){try{const db=await blobDb();await new Promise((res,rej)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(file,k);t.oncomplete=()=>res();t.onerror=()=>rej(t.error)})}catch(err){sessionFiles.set(k,file)}}
async function downloadFile(k,n){try{let file=sessionFiles.get(k);if(!file){const db=await blobDb();file=await new Promise((res,rej)=>{const r=db.transaction('files','readonly').objectStore('files').get(k);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}if(!file){toast('File not found in this browser. Uploaded files are device-specific.');return}const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast('Cannot retrieve locally stored file: '+e.message)}}
async function uploadDocs(e,jid){const files=Array.from(e.target.files||[]);if(!files.length)return;const type=$('#documentType')?.value||'Other';let count=0;for(const f of files){const prev=state.documents.filter(d=>d.jobId===jid&&d.type===type&&d.name===f.name);let ver=prev.length?Math.max(...prev.map(x=>x.version))+1:1;let blobKey=Date.now()+'-'+Math.random().toString(36).slice(2);try{await storeBlob(blobKey,f);state.documents.push({id:'DOC-'+Date.now()+count,jobId:jid,type,name:f.name,version:ver,blobKey,size:f.size,by:ui.role+' (demo)',date:new Date().toLocaleString('en-IN')});count++}catch(err){toast('Unable to store '+f.name+': '+err.message)}}if(count){audit('Uploaded '+count+' document(s) for '+jid,'Documents');toast(count+' document(s) stored in browser'+(sessionFiles.size?' (session-only fallback in this browser)':'')+'.');render()}}
function createAirlinePack(jid){const d=state.documents.filter(x=>x.jobId===jid);const required=['MAWB Copy','Commercial Invoice','Packing List'];const miss=required.filter(x=>!d.some(v=>v.type===x));if(miss.length){toast('Pack not ready. Missing: '+miss.join(', '));return}audit('Marked airline document pack ready for '+jid+' (local only)','Documents');toast('Documentation checklist complete. Pack marked ready locally; nothing was sent to an airline.');}
function downloadManifest(jid){const j=state.jobs.find(x=>x.id===jid),ds=state.documents.filter(d=>d.jobId===jid);let txt='DOCUMENTATION MANIFEST\nJob: '+jid+'\nCustomer: '+j.customer+'\nMAWB: '+j.mawb+'\n\n'+ds.map(d=>`${d.type} | ${d.name} | v${d.version} | ${d.date}`).join('\n');downloadText(txt,jid+'-manifest.txt','text/plain')}
function documents(){const ds=state.documents;return `${head('Document Centre','One searchable repository for AWBs, shipment paperwork and airline handoff packs.',`<button class="btn primary" onclick="openModal('upload')">⇧ Upload documents</button>`)}<div class="grid three"><div class="metric"><div class="mlabel">Stored documents</div><div class="mval">${ds.length}</div></div><div class="metric"><div class="mlabel">Jobs with documents</div><div class="mval">${new Set(ds.map(d=>d.jobId)).size}</div></div><div class="metric"><div class="mlabel">Document versions</div><div class="mval">${ds.filter(d=>d.version>1).length}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>By shipment</h3><small>Choose a job to upload its complete airline packet</small></div><div class="tablebox"><table class="table"><thead><tr><th>Job ID</th><th>Client / lane</th><th>MAWB</th><th>Attachments</th><th>MAWB copy</th><th>Invoice / packing list</th><th>Open</th></tr></thead><tbody>${state.jobs.map(j=>{let d=ds.filter(x=>x.jobId===j.id);return `<tr><td class="strong">${j.id}</td><td>${esc(j.customer)}<br><small>${esc(j.lane)}</small></td><td>${esc(j.mawb||'—')}</td><td>${d.length} file(s)</td><td>${badge(d.some(x=>x.type==='MAWB Copy')?'Attached':'Missing')}</td><td>${badge(d.some(x=>x.type==='Commercial Invoice')&&d.some(x=>x.type==='Packing List')?'Complete':'Incomplete')}</td><td><button class="btn small" onclick="openJob('${j.id}','docs')">Open pack →</button></td></tr>`}).join('')}</tbody></table></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Recent uploaded files</h3><small>Locally saved browser documents</small></div>${docsTable(ds.slice().reverse().slice(0,12))}</div>`}
function jobCosts(j){if(!canFinance())return noAccess();const t=totals(j);return `<div class="split"><div><div class="subhead">Revenue & cost allocation</div><div class="formgrid" style="grid-template-columns:repeat(3,1fr)">${field('Selling revenue (original currency)','c_sell',j.sell,'number',{extra:'step="0.01" oninput="profitPreview()"'})}${select('Revenue currency','c_currency',j.currency,['INR','USD','AED','EUR'],{extra:'onchange="salesCurrencyChange()"'})}${field('FX conversion to INR','c_fx',j.fx,'number',{extra:'step="0.0001" oninput="profitPreview()"'})}</div><div class="subhead" style="margin-top:23px">Individual cost heads — INR</div><div class="smalltxt muted" style="margin-bottom:8px">Cost head · amount · currency · FX to INR</div><div class="costrows">${COST_HEADS.map((x,i)=>`<div class="costrow"><label>${x}</label><input aria-label="${x} amount" type="number" name="c_${i}" value="${j.costs[i]||0}" step="0.01" oninput="profitPreview()"><select aria-label="${x} currency" name="c_cur_${i}" onchange="costCurrencyChange(${i})">${['INR','USD','AED','EUR'].map(v=>`<option ${v===((j.costCurrencies||[])[i]||'INR')?'selected':''}>${v}</option>`).join('')}</select><input aria-label="${x} FX to INR" title="Exchange rate to INR" name="c_fx_${i}" type="number" step="0.0001" min="0.0001" value="${(j.costFx||[])[i]||1}" oninput="profitPreview()"></div>`).join('')}</div></div><div><div class="sidepanel" style="position:sticky;top:92px"><div class="subhead">Live shipment profitability</div><div id="profitPreview">${profitNumbers(t,j.currency)}</div><div class="note" style="margin-top:15px">Gross profit = revenue in INR − allocated cost heads. Partner profit splits are configured separately on the Profit sharing tab.</div></div></div></div>`}
function profitNumbers(t,c='INR'){return `<div class="totalrow"><span>Selling amount (INR)</span><strong>${money(t.sell)}</strong></div><div class="totalrow"><span>Total direct costs</span><strong>${money(t.cost)}</strong></div><div class="divider"></div><div class="totalrow big"><span>Gross profit</span><span class="${t.profit>=0?'up':'down'}">${money(t.profit)}</span></div><div class="totalrow"><span>Profit margin</span><strong class="${t.margin>=0?'up':'down'}">${t.margin.toFixed(2)}%</strong></div><div class="progress"><span style="width:${Math.max(0,Math.min(100,t.margin))}%"></span></div>`}
function salesCurrencyChange(){let c=$('[name=c_currency]').value;$('[name=c_fx]').value=state.settings.fx[c]||1;profitPreview()}
function costCurrencyChange(i){let c=$('[name=c_cur_'+i+']').value;$('[name=c_fx_'+i+']').value=state.settings.fx[c]||1;profitPreview()}
function profitPreview(){let cost=COST_HEADS.reduce((s,x,i)=>s+(+$('[name=c_'+i+']')?.value||0)*(+$('[name=c_fx_'+i+']')?.value||1),0),sell=(+$('[name=c_sell]')?.value||0)*(+$('[name=c_fx]')?.value||1),t={cost,sell,profit:sell-cost,margin:sell?(sell-cost)/sell*100:0};if($('#profitPreview'))$('#profitPreview').innerHTML=profitNumbers(t)}
function activeShare(j){return state.shares.find(x=>x.jobId===j.id)||state.shares.find(x=>!x.jobId&&x.lane===j.lane)}
function jobSharing(j){if(!canProfit())return noAccess();const t=totals(j),s=activeShare(j);return `<div class="split"><div><div class="subhead">Profit distribution on ${esc(j.lane)}</div><div class="note">You can define a default profit-sharing ratio for a lane/project and override it for an individual shipment with management permission.</div>${s?`<div class="cardpad"><div class="subhead">${s.jobId?'Shipment-specific override':'Lane default'} — ${s.parts.reduce((n,p)=>n+p.pct,0)}% allocated</div><table class="table"><thead><tr><th>Partner / person</th><th>Ratio</th><th>Amount from gross profit</th></tr></thead><tbody>${s.parts.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.pct}%</td><td>${money(Math.max(0,t.profit)*p.pct/100)}</td></tr>`).join('')}<tr><td><strong>Company / undistributed</strong></td><td>${Math.max(0,100-s.parts.reduce((a,p)=>a+p.pct,0))}%</td><td><strong>${money(Math.max(0,t.profit)*(100-s.parts.reduce((a,p)=>a+p.pct,0))/100)}</strong></td></tr></tbody></table></div>`:'<p class="muted" style="margin:22px 0">No profit-sharing rules set for this lane. Company retains 100% by default.</p>'}<button class="btn primary" onclick="openShare('${j.id}')">${s?'Edit / override sharing':'Configure profit sharing'}</button></div><div class="sidepanel"><div class="subhead">Profit basis</div>${profitNumbers(t)}<p class="smalltxt muted" style="line-height:1.7;margin-top:15px">Split is calculated on positive shipment gross profit in this demo. Rules for losses, clawbacks, taxes, cash realization and payouts require client approval before production.</p></div></div>`}
function jobBilling(j){const inv=state.invoices.filter(x=>x.jobId===j.id),ds=state.documents.filter(x=>x.jobId===j.id);return `<div class="subhead">Linked financial documents <button class="btn small primary" onclick="newInvoice('${j.id}')">＋ Invoice for this job</button></div><div class="tablebox"><table class="table"><thead><tr><th>Document no.</th><th>Type</th><th>Amount</th><th>Outstanding</th><th>Due date</th><th>Status</th><th>Open</th></tr></thead><tbody>${inv.map(i=>`<tr><td>${i.id}</td><td>${i.type}</td><td>${money(invTotal(i).total)}</td><td>${money(invTotal(i).balance)}</td><td>${fmtDate(i.due)}</td><td>${badge(i.status)}</td><td><button class="btn small" onclick="viewInvoice('${i.id}')">View</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No invoices attached to this job.</td></tr>'}</tbody></table></div><div class="subhead" style="margin-top:24px">Activity and pending paperwork</div><div class="grid two"><div class="sidepanel">${state.tasks.filter(t=>t.jobId===j.id).map(t=>`<div class="minirow"><span>${esc(t.title)}</span>${badge(t.done?'Complete':t.priority)}</div>`).join('')||'<p class="muted">No outstanding tasks</p>'}</div><div class="sidepanel"><div class="minirow"><span>Documents filed</span><strong>${ds.length}</strong></div><div class="minirow"><span>Quotation linked</span><strong>${state.quotes.filter(q=>q.jobId===j.id).length}</strong></div><div class="minirow"><span>Booking legs</span><strong>${state.bookings.filter(b=>b.jobId===j.id).length}</strong></div></div></div>`}
function stock(){return `${head('AWB Stock & Allocation','Track carrier-issued AWB ranges, station assignment and utilization.',`<button class="btn primary" onclick="openModal('stock')">＋ Add AWB stock</button>`)}<div class="grid three">${[['AWB numbers in range',state.awbstock.reduce((s,x)=>s+x.to-x.from+1,0)],['Allocated AWB numbers',state.awbstock.reduce((s,x)=>s+x.used.length,0)],['Open stock ranges',state.awbstock.filter(x=>x.status==='Active').length]].map(([t,n])=>`<div class="metric"><div class="mlabel">${t}</div><div class="mval">${n}</div></div>`).join('')}</div><div class="card cardpad section"><div class="cardtitle"><h3>Airline AWB stock register</h3><small>Local allocation records, not live inventory</small></div><div class="tablebox"><table class="table"><thead><tr><th>Airline</th><th>Prefix</th><th>Station</th><th>Number range</th><th>Used</th><th>Remaining</th><th>Utilization</th><th>Status</th><th></th></tr></thead><tbody>${state.awbstock.map(s=>{let total=s.to-s.from+1,used=s.used.length;return `<tr><td class="strong">${s.airline}</td><td>${s.prefix}</td><td>${s.station}</td><td>${s.from} – ${s.to}</td><td>${used}</td><td>${total-used}</td><td><div class="progress" style="min-width:75px"><span style="width:${used/total*100}%"></span></div></td><td>${badge(s.status)}</td><td><button class="btn small" onclick="allocateAWB('${s.id}')">Allocate number</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function allocateAWB(sid){const s=state.awbstock.find(x=>x.id===sid);let n;for(let a=s.from;a<=s.to;a++)if(!s.used.includes(a)){n=a;break}if(!n){toast('No unused AWB numbers in the range.');return}ui.modal='allocate:'+sid+':'+n;render()}
function quotes(){return `${head('Quotes & Tariffs','Contract pricing, airline ad-hoc rates and customer quotations with approval tracking.',`<button class="btn" onclick="openModal('rate')">＋ New ad-hoc rate</button><button class="btn primary" onclick="openModal('quote')">＋ New quotation</button>`)}<div class="grid four"><div class="metric"><div class="mlabel">Active tariffs</div><div class="mval">${state.tariffs.length}</div></div><div class="metric"><div class="mlabel">Open quotations</div><div class="mval">${state.quotes.filter(q=>q.status==='Pending Approval').length}</div></div><div class="metric"><div class="mlabel">Approved quotes</div><div class="mval">${state.quotes.filter(q=>q.status==='Approved').length}</div></div><div class="metric"><div class="mlabel">Quote-to-job links</div><div class="mval">${state.quotes.filter(q=>q.jobId).length}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Customer quotations</h3><small>Request → approval → booking / job</small></div><div class="tablebox"><table class="table"><thead><tr><th>Quote no.</th><th>Customer</th><th>Route</th><th>Airline</th><th>Selling quote</th><th>Chargeable</th><th>Valid until</th><th>State</th><th>Action</th></tr></thead><tbody>${state.quotes.map(q=>`<tr><td class="strong">${q.id}</td><td>${esc(q.customer)}</td><td>${esc(q.lane)}</td><td>${esc(q.airline)}</td><td>${money(q.rate,q.currency)}</td><td>${q.chargeable} kg</td><td>${fmtDate(q.valid)}</td><td>${badge(q.status)}</td><td><button class="btn small" onclick="approveQuote('${q.id}')">${q.status==='Approved'?'Create job':'Approve'}</button></td></tr>`).join('')}</tbody></table></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Contract & ad-hoc airline rates</h3><small>Entered manually; no live rate engine</small></div><div class="tablebox"><table class="table"><thead><tr><th>Airline</th><th>Lane</th><th>Type</th><th>Min charge</th><th>Per kg</th><th>Valid until</th><th>Currency</th></tr></thead><tbody>${state.tariffs.map(r=>`<tr><td class="strong">${esc(r.airline)}</td><td>${esc(r.lane)}</td><td>${badge(r.type)}</td><td>${money(r.min,r.currency)}</td><td>${money(r.perkg,r.currency)}</td><td>${fmtDate(r.valid)}</td><td>${r.currency}</td></tr>`).join('')}</tbody></table></div></div>`}
function approveQuote(qid){const q=state.quotes.find(x=>x.id===qid);if(q.status!=='Approved'){q.status='Approved';audit('Approved quote '+qid,'Sales');render();toast('Quotation approved locally.');return}if(q.jobId){openJob(q.jobId);return}ui.modal='quotejob:'+qid;render()}
function finance(){if(!canFinance())return noAccess();let invoices=state.invoices.filter(i=>i.type==='Tax Invoice'),out=invoices.reduce((s,i)=>s+invTotal(i).balance,0),over=invoices.filter(i=>i.due<TODAY&&invTotal(i).balance>0);return `${head('Invoices & Receivables','Create GST-ready draft invoices, proformas, debit/credit notes and record payments.',`<button class="btn" onclick="csv('invoices')">⇩ Export receivables</button><button class="btn primary" onclick="newInvoice()">＋ Create document</button>`)}<div class="grid four"><div class="metric"><div class="mlabel">Raised tax invoices</div><div class="mval">${invoices.length}</div></div><div class="metric"><div class="mlabel">Outstanding (incl. GST)</div><div class="mval">${money(out)}</div></div><div class="metric"><div class="mlabel">Overdue receivables</div><div class="mval">${money(over.reduce((s,i)=>s+invTotal(i).balance,0))}</div></div><div class="metric"><div class="mlabel">Part / full payments</div><div class="mval">${money(invoices.reduce((s,i)=>s+(+i.paid||0),0))}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Sales documents register</h3><button class="btn small" onclick="go('tasks')">Payment follow-ups →</button></div><div class="tablebox"><table class="table"><thead><tr><th>Document number</th><th>Type</th><th>Client</th><th>Job ID</th><th>Created</th><th>Due</th><th>Gross amount</th><th>Paid</th><th>Outstanding</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.invoices.map(i=>`<tr><td><button class="linkbutton" onclick="viewInvoice('${i.id}')">${i.id}</button></td><td>${i.type}</td><td>${esc(i.customer)}</td><td><button class="linkbutton" onclick="openJob('${i.jobId}','billing')">${i.jobId||'—'}</button></td><td>${fmtDate(i.date)}</td><td>${fmtDate(i.due)}</td><td>${money(invTotal(i).total)}</td><td>${money(i.paid)}</td><td>${money(invTotal(i).balance)}</td><td>${badge(invTotal(i).balance===0?'Paid':i.due<TODAY&&i.type==='Tax Invoice'?'Overdue':i.status)}</td><td><button class="btn small" onclick="recordPayment('${i.id}')">Record payment</button></td></tr>`).join('')}</tbody></table></div></div><div class="grid two section"><div class="card cardpad"><div class="cardtitle"><h3>Receivables ageing</h3><small>Unpaid invoices by due date</small></div>${[['Not yet due',invoices.filter(i=>i.due>=TODAY)],['1–30 days overdue',invoices.filter(i=>dateDiff(i.due,TODAY)>=1&&dateDiff(i.due,TODAY)<=30)],['31+ days overdue',invoices.filter(i=>dateDiff(i.due,TODAY)>30)]].map(([name,arr])=>`<div class="minirow"><span>${name}</span><strong>${money(arr.reduce((s,i)=>s+invTotal(i).balance,0))}</strong></div>`).join('')}</div><div class="card cardpad"><div class="cardtitle"><h3>Reminder configuration</h3><small>Simulation / workflow prototype</small></div><p class="muted">Configured reminder schedule: ${state.settings.remindBefore} days before due date, on due date, then every ${state.settings.remindAfter} days overdue until the balance is cleared.</p><button class="btn" onclick="go('tasks')">Manage reminders & follow-ups</button></div></div>`}
function dateDiff(a,b){return Math.round((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/86400000)}
function newInvoice(jobId=''){let i={id:'INV-26-'+String(76+state.invoices.length).padStart(3,'0'),type:'Tax Invoice',jobId:jobId||state.jobs[0]?.id||'',customer:state.jobs.find(x=>x.id===jobId)?.customer||'',date:TODAY,due:'2026-11-17',email:'',lines:[{desc:'Air freight & handling',hsn:'996531',qty:1,rate:0,gst:18}],paid:0,status:'Draft',reminders:[],notes:''};ui.invDraft=i;navigate('invoiceform')}
function editInvoice(k){ui.invDraft=clone(state.invoices.find(x=>x.id===k));navigate('invoiceform')}
function invoiceForm(){if(!canFinance())return noAccess();const i=ui.invDraft||state.invoices[0];if(!ui.invDraft)ui.invDraft=clone(i);const t=invTotal(i);return `${head(i.id&&state.invoices.find(x=>x.id===i.id)?'Edit '+i.type:'Create financial document','Customizable tax invoices, proformas, quotations, debit notes and credit notes.',`<button class="btn" onclick="go('finance')">Cancel</button><button class="btn primary" onclick="saveInvoice()">✓ Save document</button>`)}<div class="card cardpad"><div class="formgrid">${select('Document type','i_type',i.type,['Tax Invoice','Proforma Invoice','Quotation','Debit Note','Credit Note'],{extra:'onchange="syncInv()"'})}${field('Document number','i_id',i.id)}${field('Issue date','i_date',i.date,'date')}${field('Due date','i_due',i.due,'date')}${select('Linked job / shipment','i_jobId',i.jobId,['',...state.jobs.map(j=>j.id)],{extra:'onchange="invoiceJobChanged(this.value)"'})}${select('Billed to (customer)','i_customer',i.customer,['',...new Set([...state.jobs.map(j=>j.customer),...state.invoices.map(j=>j.customer)])],{extra:'onchange="syncInv()"'})}${field('Recipient email(s)','i_email',i.email,'text',{placeholder:'finance@customer.com; accounts@customer.com',w:'w2'})}</div><div class="subhead" style="margin-top:25px">Invoice line items <button class="btn small" onclick="addInvLine()">＋ Add line</button></div><div class="tablebox"><table class="table"><thead><tr><th>Description</th><th>HSN / SAC</th><th>Quantity</th><th>Rate</th><th>GST %</th><th>Amount</th><th></th></tr></thead><tbody id="invLines">${invoiceLinesHTML(i)}</tbody></table></div><div class="grid two section"><div class="sidepanel"><div class="subhead">Company / payment details</div><p><strong>${esc(state.settings.company)}</strong><br><span class="muted">${esc(state.settings.address)}</span></p><p>GSTIN: <strong>${esc(state.settings.gstin||'Not configured')}</strong></p><p>Bank: <strong>${esc(state.settings.bank)}</strong></p><button class="btn small" onclick="go('settings')">Configure billing settings</button></div><div class="sidepanel"><div class="totalrow"><span>Taxable amount</span><strong id="it_sub">${money(t.sub)}</strong></div><div class="totalrow"><span>GST</span><strong id="it_gst">${money(t.gst)}</strong></div><div class="totalrow big"><span>Total invoice</span><span id="it_total">${money(t.total)}</span></div></div></div>${textArea('Notes / payment terms','i_notes',i.notes)}<div class="formactions"><button class="btn" onclick="saveInvoice(true)">Save & preview</button><button class="btn primary" onclick="saveInvoice()">Save document</button></div></div>`}
function invoiceLinesHTML(i){return i.lines.map((l,k)=>`<tr><td><input class="inline-input" style="min-width:180px" value="${esc(l.desc)}" oninput="setInvLine(${k},'desc',this.value)"></td><td><input class="inline-input" style="width:95px" value="${esc(l.hsn)}" oninput="setInvLine(${k},'hsn',this.value)"></td><td><input class="inline-input" style="width:67px" type="number" min="0" value="${l.qty}" oninput="setInvLine(${k},'qty',+this.value)"></td><td><input class="inline-input" style="width:115px" type="number" min="0" value="${l.rate}" oninput="setInvLine(${k},'rate',+this.value)"></td><td><select class="inline-input" style="width:74px" onchange="setInvLine(${k},'gst',+this.value)">${[0,5,12,18,28].map(a=>`<option value="${a}" ${+l.gst===a?'selected':''}>${a}%</option>`).join('')}</select></td><td><strong>${money((+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100))}</strong></td><td><button class="btn small danger" onclick="removeInvLine(${k})">×</button></td></tr>`).join('')}
function syncInv(){let i=ui.invDraft;if(!i)return;for(const x of ['type','id','date','due','jobId','customer','email','notes']){let el=$('[name=i_'+x+']');if(el)i[x]=el.value}const t=invTotal(i);for(const [sel,v] of [['#it_sub',money(t.sub)],['#it_gst',money(t.gst)],['#it_total',money(t.total)]])if($(sel))$(sel).textContent=v}
function invoiceJobChanged(v){syncInv();const j=state.jobs.find(x=>x.id===v);if(j){ui.invDraft.customer=j.customer;let x=$('[name=i_customer]');if(x)x.value=j.customer}syncInv()}
function setInvLine(k,f,v){ui.invDraft.lines[k][f]=v;syncInv();const tr=$$('#invLines tr')[k],l=ui.invDraft.lines[k];if(tr)tr.querySelector('td:nth-child(6)').textContent=money((+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100))}
function addInvLine(){syncInv();ui.invDraft.lines.push({desc:'',hsn:'996531',qty:1,rate:0,gst:18});$('#invLines').innerHTML=invoiceLinesHTML(ui.invDraft);syncInv()}
function removeInvLine(k){syncInv();if(ui.invDraft.lines.length===1){toast('At least one line item is required.');return}ui.invDraft.lines.splice(k,1);$('#invLines').innerHTML=invoiceLinesHTML(ui.invDraft);syncInv()}
function saveInvoice(preview=false){if(!canFinance())return;syncInv();let i=ui.invDraft;if(!i.customer||!i.id||!i.date){toast('Enter document number, customer and date.');return}if(i.lines.some(x=>!x.desc||+x.qty<0||+x.rate<0)){toast('Enter valid item descriptions and amounts.');return}const pos=state.invoices.findIndex(x=>x.id===i.id);if(pos>=0)state.invoices[pos]=clone(i);else state.invoices.unshift(clone(i));audit('Saved '+i.type+' '+i.id,'Finance');toast('Document saved locally.');preview?viewInvoice(i.id):navigate('finance')}
function viewInvoice(k){ui.invId=k;navigate('invoiceview')}
function invoiceView(){const i=state.invoices.find(x=>x.id===ui.invId);if(!i)return '<p>Document not found.</p>';const t=invTotal(i);return `${head(i.id+' · '+i.type,'Professional document preview — download through browser Print → Save as PDF.',`<button class="btn" onclick="editInvoice('${i.id}')">✎ Edit</button><button class="btn" onclick="window.print()">⇩ Save as PDF / Print</button><button class="btn" onclick="emailInvoice('${i.id}')">✉ Prepare email</button><button class="btn primary" onclick="recordPayment('${i.id}')">＋ Record payment</button>`)}<div class="bill"><h2>${esc(i.type)}</h2><div class="minirow" style="margin:19px 0 25px"><strong>Document # ${i.id}</strong><span>${fmtDate(i.date)}</span></div><div class="billgrid"><div><h4>Issued by</h4><strong>${esc(state.settings.company)}</strong><p>${esc(state.settings.address)}</p><p>GSTIN: ${esc(state.settings.gstin||'Not set')}</p></div><div><h4>Billed to</h4><strong>${esc(i.customer)}</strong><p>Linked shipment: ${esc(i.jobId)}</p><p>${esc(i.email)}</p><p>Due ${fmtDate(i.due)}</p></div></div><table class="table" style="margin-top:24px"><thead><tr><th>Description</th><th>HSN/SAC</th><th>Qty</th><th>Rate</th><th>GST</th><th class="right">Amount</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${esc(l.desc)}</td><td>${esc(l.hsn)}</td><td>${l.qty}</td><td>${money(l.rate)}</td><td>${l.gst}%</td><td class="right">${money((+l.qty||0)*(+l.rate||0)*(1+(+l.gst||0)/100))}</td></tr>`).join('')}</tbody></table><div style="width:300px;max-width:100%;margin:25px 0 0 auto"><div class="totalrow"><span>Taxable</span><strong>${money(t.sub)}</strong></div><div class="totalrow"><span>GST</span><strong>${money(t.gst)}</strong></div><div class="totalrow big"><span>Total</span><strong>${money(t.total)}</strong></div><div class="totalrow"><span>Payment received</span><strong>${money(i.paid)}</strong></div><div class="totalrow"><span>Balance due</span><strong>${money(t.balance)}</strong></div></div><div class="divider"></div><p><strong>Bank:</strong> ${esc(state.settings.bank)}</p><p><strong>Notes:</strong> ${esc(i.notes||'Subject to agreed payment terms.')}</p><p class="muted">Generated from a demonstration application. Verify tax treatment, supply type, GSTIN, HSN/SAC and e-invoicing eligibility before use.</p></div><div class="card cardpad section"><div class="cardtitle"><h3>Payment reminders & history</h3><button class="btn small" onclick="simulateReminder('${i.id}')">Record reminder (demo)</button></div>${i.reminders.length?i.reminders.map(r=>`<div class="minirow"><span>${esc(r.date)} — ${esc(r.method)} (${esc(r.email)})</span><span class="badge info">Simulated</span></div>`).join(''):'<p class="muted">No reminders recorded for this invoice.</p>'}</div>`}
function emailInvoice(k){const i=state.invoices.find(x=>x.id===k);let subject=encodeURIComponent(`${i.type} ${i.id} — ${state.settings.company}`),body=encodeURIComponent(`Dear ${i.customer},\n\nPlease find details of ${i.type} ${i.id} for job ${i.jobId}.\nAmount: ${money(invTotal(i).total)}\nOutstanding: ${money(invTotal(i).balance)}\nDue date: ${fmtDate(i.due)}\n\nKindly arrange payment as agreed.\n\n${state.settings.company}`);window.open('mailto:'+i.email.replace(/;/g,',')+'?subject='+subject+'&body='+body,'_self');toast('Email draft opened. Attach the PDF manually; no email sent automatically.');}
function recordPayment(k){ui.modal='payment:'+k;render()}
function simulateReminder(k){const i=state.invoices.find(x=>x.id===k);if(invTotal(i).balance===0){toast('Invoice fully paid. Reminder stopped.');return}i.reminders.unshift({date:new Date().toLocaleString('en-IN'),email:i.email,method:'Manual reminder simulation',balance:invTotal(i).balance});audit('Recorded simulated reminder for '+k,'Finance');render();toast('Reminder logged as simulated. No external email sent.')}
function payables(){if(!canFinance())return noAccess();const out=state.payables.reduce((s,x)=>s+Math.max(0,x.amount-x.paid),0);return `${head('Accounts Payable','Vendor and airline bills, settlements, outstanding amounts and allocation to shipment costs.',`<button class="btn" onclick="csv('payables')">⇩ Export payables</button><button class="btn primary" onclick="openModal('payable')">＋ Add vendor bill</button>`)}<div class="grid three"><div class="metric"><div class="mlabel">Vendor bills</div><div class="mval">${state.payables.length}</div></div><div class="metric"><div class="mlabel">Total unpaid</div><div class="mval">${money(out)}</div></div><div class="metric"><div class="mlabel">Bills settled in full</div><div class="mval">${state.payables.filter(x=>x.paid>=x.amount).length}</div></div></div><div class="card cardpad section"><div class="tablebox"><table class="table"><thead><tr><th>Vendor bill</th><th>Vendor</th><th>Shipment</th><th>Cost head</th><th>Total</th><th>Paid</th><th>Outstanding</th><th>Due date</th><th>Action</th></tr></thead><tbody>${state.payables.map(x=>`<tr><td class="strong">${x.id}</td><td>${esc(x.vendor)}</td><td><button class="linkbutton" onclick="openJob('${x.jobId}','costs')">${x.jobId}</button></td><td>${esc(x.head)}</td><td>${money(x.amount,x.currency)}</td><td>${money(x.paid,x.currency)}</td><td>${money(Math.max(0,x.amount-x.paid),x.currency)}</td><td>${fmtDate(x.due)}</td><td><button class="btn small" onclick="ui.modal='vendorpay:${x.id}';render()">Record payment</button></td></tr>`).join('')}</tbody></table></div></div><div class="note section">In the demo, vendor bills and shipment cost heads are separate editable records. Production implementation should reconcile posted vendor costs with approved shipment cost allocations and the general ledger to prevent double counting.</div>`}
function partners(){if(!canProfit())return noAccess();let periodJobs=periodFilteredJobs();let profit=periodJobs.reduce((n,j)=>n+totals(j).profit,0);return `${head('Profit & Partner Sharing','Set profit splits by lane or project. Authorised managers may override a specific shipment.',`<button class="btn" onclick="csv('shares')">⇩ Export distributions</button><button class="btn primary" onclick="openShare()">＋ Create sharing rule</button>`)}<div class="filters"><label>Reporting period</label>${periodSelect()}</div><div class="grid three"><div class="metric"><div class="mlabel">Overall shipment gross profit</div><div class="mval">${money(profit)}</div></div><div class="metric"><div class="mlabel">Configured lane / project rules</div><div class="mval">${state.shares.filter(x=>!x.jobId).length}</div></div><div class="metric"><div class="mlabel">Shipment overrides</div><div class="mval">${state.shares.filter(x=>x.jobId).length}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Profit-sharing rules</h3><small>Distribution calculated on positive shipment profit</small></div><div class="tablebox"><table class="table"><thead><tr><th>Scope</th><th>Lane / project</th><th>Participants & ratios</th><th>Allocated</th><th>Company retained</th><th>Action</th></tr></thead><tbody>${state.shares.map(x=>{let pct=x.parts.reduce((a,p)=>a+p.pct,0);return `<tr><td>${x.jobId?badge('Job override'):badge('Lane default')}</td><td>${esc(x.lane)}${x.jobId?`<br><small>${x.jobId}</small>`:''}</td><td>${x.parts.map(p=>esc(p.name)+' '+p.pct+'%').join(' · ')}</td><td>${pct}%</td><td>${100-pct}%</td><td><button class="btn small" onclick="editShare('${x.id}')">Edit</button></td></tr>`}).join('')}</tbody></table></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Job-wise distribution ledger</h3><small>Use this for partner settlements and monthly / quarterly / yearly reports</small></div><div class="tablebox"><table class="table"><thead><tr><th>Job</th><th>Lane</th><th>Selling</th><th>Cost</th><th>Gross profit</th><th>Individuals' share</th><th>Company retained</th><th></th></tr></thead><tbody>${periodJobs.map(j=>{let t=totals(j),s=activeShare(j),pct=s?s.parts.reduce((v,p)=>v+p.pct,0):0,base=Math.max(0,t.profit);return `<tr><td class="strong">${j.id}</td><td>${esc(j.lane)}</td><td>${money(t.sell)}</td><td>${money(t.cost)}</td><td>${money(t.profit)}</td><td>${money(base*pct/100)}</td><td>${money(base*(100-pct)/100)}</td><td><button class="btn small" onclick="openJob('${j.id}','sharing')">View</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function openShare(jobId=''){ui.shareDraft={id:'',lane:jobId?state.jobs.find(j=>j.id===jobId).lane:'',jobId,parts:[{name:TEAM[0],pct:40},{name:TEAM[1],pct:30},{name:TEAM[2],pct:20},{name:TEAM[3],pct:10}]};ui.modal='share';render()}
function editShare(id){ui.shareDraft=clone(state.shares.find(s=>s.id===id));ui.modal='share';render()}
function shareRows(){let s=ui.shareDraft;return s.parts.map((p,k)=>`<div class="rowflex" style="margin:8px 0"><select style="flex:1;padding:8px;border:1px solid #dce4ee;border-radius:6px" onchange="ui.shareDraft.parts[${k}].name=this.value">${[...new Set([...state.partners.map(p=>p.name),...TEAM,p.name])].map(n=>`<option ${n===p.name?'selected':''}>${esc(n)}</option>`).join('')}</select><input type="number" style="width:88px;padding:8px;border:1px solid #dce4ee;border-radius:6px" min="0" max="100" step="0.01" value="${p.pct}" oninput="ui.shareDraft.parts[${k}].pct=+this.value;shareTotal()"><span>%</span><button class="btn small danger" onclick="ui.shareDraft.parts.splice(${k},1);$('#shareRows').innerHTML=shareRows();shareTotal()">×</button></div>`).join('')}
function shareTotal(){let tot=ui.shareDraft.parts.reduce((a,p)=>a+(+p.pct||0),0);if($('#shareTotal'))$('#shareTotal').textContent=tot.toFixed(2)+'% allocated · '+(100-tot).toFixed(2)+'% company retained';if($('#shareTotal'))$('#shareTotal').style.color=tot>100?'#bc3948':''}
function saveShare(){if(!canProfit())return;const s=ui.shareDraft;s.lane=$('#share_lane').value;s.jobId=$('#share_job').value;if(s.jobId){s.lane=state.jobs.find(x=>x.id===s.jobId)?.lane||s.lane}let sum=s.parts.reduce((a,p)=>a+(+p.pct||0),0);if(!s.lane||sum>100.0001||sum<0||new Set(s.parts.map(x=>x.name)).size!==s.parts.length){toast('Enter a lane, keep ratios at or below 100%, and choose each person only once.');return}if(!s.id){let clash=state.shares.find(x=>x.jobId===s.jobId&&x.lane===s.lane);if(clash){toast('Rule already exists for this scope. Edit the existing rule.');return}s.id='PS-'+Date.now()}let pos=state.shares.findIndex(x=>x.id===s.id);pos>=0?state.shares[pos]=clone(s):state.shares.push(clone(s));audit('Updated authorized sharing ratios for '+(s.jobId||s.lane),'Profit shares');ui.modal='';render();toast('Profit-sharing rule saved and recalculated.');}
function tasks(){let open=state.tasks.filter(x=>!x.done),over=open.filter(x=>x.due<TODAY),today=open.filter(x=>x.due===TODAY);return `${head('Follow-ups & Reminders','Personal actions, invoice collection follow-ups and configurable due-date reminders.',`<button class="btn" onclick="exportReminderCalendar()">⇩ Export task calendar</button><button class="btn primary" onclick="openModal('task')">＋ New follow-up</button>`)}<div class="grid four"><div class="metric"><div class="mlabel">Due today</div><div class="mval">${today.length}</div></div><div class="metric"><div class="mlabel">Overdue</div><div class="mval down">${over.length}</div></div><div class="metric"><div class="mlabel">Upcoming</div><div class="mval">${open.filter(x=>x.due>TODAY).length}</div></div><div class="metric"><div class="mlabel">Completed</div><div class="mval">${state.tasks.filter(x=>x.done).length}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Assigned follow-up tasks</h3><small>Manual task tracking and local demo reminders</small></div><div class="tablebox"><table class="table"><thead><tr><th>Action</th><th>Client</th><th>Job / invoice</th><th>Owner</th><th>Due date</th><th>Priority</th><th>State</th><th></th></tr></thead><tbody>${state.tasks.map(t=>`<tr><td style="max-width:260px;white-space:normal"><strong>${esc(t.title)}</strong><div class="muted smalltxt">${esc(t.notes)}</div></td><td>${esc(t.customer)}</td><td>${t.jobId}<br><small>${t.invoice||'—'}</small></td><td>${esc(t.owner)}</td><td>${fmtDate(t.due)}</td><td>${badge(t.priority)}</td><td>${badge(t.done?'Complete':t.due<TODAY?'Overdue':'Open')}</td><td><button class="btn small" onclick="toggleTask('${t.id}')">${t.done?'Reopen':'Complete'}</button></td></tr>`).join('')}</tbody></table></div></div><div class="grid two section"><div class="card cardpad"><div class="cardtitle"><h3>Invoice reminder queue</h3><button class="btn link" onclick="go('finance')">Receivables →</button></div>${state.invoices.filter(i=>i.type==='Tax Invoice'&&invTotal(i).balance>0).map(i=>`<div class="minirow"><div><strong>${i.id}</strong> · ${esc(i.customer)}<div class="muted smalltxt">${money(invTotal(i).balance)} outstanding · due ${fmtDate(i.due)}</div></div><button class="btn small" onclick="simulateReminder('${i.id}')">Log reminder</button></div>`).join('')||'<p class="muted">No unpaid invoices.</p>'}</div><div class="card cardpad"><div class="cardtitle"><h3>Reminder policy (demo)</h3><button class="btn link" onclick="go('settings')">Settings →</button></div><div class="minirow"><span>Before payment due date</span><strong>${state.settings.remindBefore} days</strong></div><div class="minirow"><span>On due date</span><strong>Yes</strong></div><div class="minirow"><span>Repeat while overdue</span><strong>Every ${state.settings.remindAfter} days</strong></div><div class="minirow"><span>Stop after full payment</span><strong>Yes · by design</strong></div><div class="note" style="margin-top:12px">Scheduled sending and staff notifications require a backend mail service and scheduler. This browser-only version lets you inspect the rules and manually log a simulated reminder.</div></div></div>`}
function toggleTask(k){const t=state.tasks.find(x=>x.id===k);t.done=!t.done;audit((t.done?'Completed':'Reopened')+' follow-up '+t.id,'Tasks');render()}
function reportRows(){let map=new Map;for(const j of periodFilteredJobs()){let key=ui.reportGroup==='Customer'?j.customer:ui.reportGroup==='Lane'?j.lane:ui.reportGroup==='Airline'?j.airline:ui.reportGroup==='Salesperson'?j.owner:ui.reportGroup==='Month'?j.date.slice(0,7):j.branch;const v=map.get(key)||{name:key,revenue:0,cost:0,profit:0,count:0};const t=totals(j);v.revenue+=t.sell;v.cost+=t.cost;v.profit+=t.profit;v.count++;map.set(key,v)}return [...map.values()].sort((a,b)=>b.revenue-a.revenue)}
function reports(){if(!allowed('reports'))return noAccess();let rows=reportRows(),profitAccess=canProfit(),s=stats();return `${head('Reports & Insights','Shipment profitability, customer/lane performance, receivables, unbilled jobs and personal allocations.',`<button class="btn" onclick="csv('report')">⇩ Export CSV</button><button class="btn" onclick="window.print()">⇩ Save report as PDF</button>`)}<div class="filters"><label class="muted">Period</label>${periodSelect()}<label class="muted">Group by</label><select onchange="ui.reportGroup=this.value;render()">${['Customer','Lane','Airline','Salesperson','Month','Branch'].map(x=>`<option ${x===ui.reportGroup?'selected':''}>${x}</option>`).join('')}</select><span class="muted">Reporting currency: INR converted equivalent</span></div><div class="grid four"><div class="metric"><div class="mlabel">Total jobs</div><div class="mval">${state.jobs.length}</div></div><div class="metric"><div class="mlabel">Gross revenue</div><div class="mval">${canFinance()?money(s.revenue):'Restricted'}</div></div><div class="metric"><div class="mlabel">Cost of jobs</div><div class="mval">${canFinance()?money(s.cost):'Restricted'}</div></div><div class="metric"><div class="mlabel">Overall profit</div><div class="mval">${profitAccess?money(s.profit):'Restricted'}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>${ui.reportGroup}-wise performance</h3><small>Based on recorded shipment data</small></div><div class="tablebox"><table class="table"><thead><tr><th>${ui.reportGroup}</th><th>Shipments</th>${canFinance()?'<th>Revenue</th><th>Cost</th>':''}${profitAccess?'<th>Gross profit</th><th>Margin</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td class="strong">${esc(r.name)}</td><td>${r.count}</td>${canFinance()?`<td>${money(r.revenue)}</td><td>${money(r.cost)}</td>`:''}${profitAccess?`<td>${money(r.profit)}</td><td>${r.revenue?(r.profit/r.revenue*100).toFixed(1):0}%</td>`:''}</tr>`).join('')}</tbody></table></div></div><div class="grid two section"><div class="card cardpad"><div class="cardtitle"><h3>Unbilled / incomplete jobs</h3></div><div class="tablebox"><table class="table"><thead><tr><th>Shipment</th><th>Client</th><th>Billing state</th><th></th></tr></thead><tbody>${state.jobs.filter(j=>!state.invoices.some(i=>i.jobId===j.id&&i.type==='Tax Invoice')).map(j=>`<tr><td>${j.id}</td><td>${esc(j.customer)}</td><td>${badge('Unbilled')}</td><td><button class="btn small" onclick="newInvoice('${j.id}')">Create invoice</button></td></tr>`).join('')||'<tr><td colspan="4" class="muted">No unbilled jobs.</td></tr>'}</tbody></table></div></div><div class="card cardpad"><div class="cardtitle"><h3>Receivables ageing</h3></div>${[['Not due',0,0],['1–30d',1,30],['31–60d',31,60],['61+d',61,99999]].map(([label,lo,hi])=>{let total=state.invoices.filter(i=>i.type==='Tax Invoice'&&invTotal(i).balance>0&&(label==='Not due'?i.due>=TODAY:dateDiff(i.due,TODAY)>=lo&&dateDiff(i.due,TODAY)<=hi)).reduce((a,i)=>a+invTotal(i).balance,0);return `<div class="minirow"><span>${label}</span><strong>${canFinance()?money(total):'Restricted'}</strong></div>`}).join('')}</div></div>${profitAccess?`<div class="card cardpad section"><div class="cardtitle"><h3>Partner profit share summary</h3><small>Calculated from saved lane rules and overrides</small></div><div class="tablebox"><table class="table"><thead><tr><th>Person</th><th>Calculated allocation</th><th>Jobs covered</th></tr></thead><tbody>${shareReport().map(x=>`<tr><td class="strong">${esc(x.name)}</td><td>${money(x.amount)}</td><td>${x.jobs}</td></tr>`).join('')}</tbody></table></div></div>`:''}`}

function periodFilteredJobs(){const now=new Date(TODAY+'T12:00:00');return state.jobs.filter(j=>{let dt=new Date((j.date||j.created||TODAY)+'T12:00:00');if(ui.period==='This month')return dt.getFullYear()===now.getFullYear()&&dt.getMonth()===now.getMonth();if(ui.period==='This quarter')return dt.getFullYear()===now.getFullYear()&&Math.floor(dt.getMonth()/3)===Math.floor(now.getMonth()/3);if(ui.period==='This year')return dt.getFullYear()===now.getFullYear();return true})}
function periodSelect(){return `<select onchange="ui.period=this.value;render()">${['All time','This month','This quarter','This year'].map(v=>`<option ${ui.period===v?'selected':''}>${v}</option>`).join('')}</select>`}

function shareReport(){let d={};for(const j of periodFilteredJobs()){let s=activeShare(j);if(!s)continue;for(const p of s.parts){if(!d[p.name])d[p.name]={name:p.name,amount:0,jobs:0};d[p.name].amount+=Math.max(0,totals(j).profit)*p.pct/100;d[p.name].jobs++}}return Object.values(d).sort((a,b)=>b.amount-a.amount)}
function customers(){let customers=[...new Set([...state.jobs.map(x=>x.customer),...state.quotes.map(x=>x.customer),...state.invoices.map(x=>x.customer)])];const vendors=[...new Set([...state.payables.map(x=>x.vendor),...state.jobs.map(x=>x.airline),...(state.parties||[]).filter(p=>p.type==='Vendor').map(p=>p.name)])];customers=[...new Set([...customers,...(state.parties||[]).filter(p=>p.type==='Customer').map(p=>p.name)])];return `${head('Customers & Vendors','Shared records across shipment jobs, quotations, invoices, booking and finance.',`<button class="btn primary" onclick="openModal('party')">＋ Add party</button>`)}<div class="grid two"><div class="card cardpad"><div class="cardtitle"><h3>Customers</h3><small>${customers.length} records</small></div><div class="tablebox"><table class="table"><thead><tr><th>Customer</th><th>Shipments</th><th>Invoices</th><th>Revenue</th></tr></thead><tbody>${customers.map(c=>`<tr><td><span class="customer-id">${esc(c.charAt(0))}</span><strong>${esc(c)}</strong></td><td>${state.jobs.filter(j=>j.customer===c).length}</td><td>${state.invoices.filter(i=>i.customer===c).length}</td><td>${canFinance()?money(state.jobs.filter(j=>j.customer===c).reduce((a,j)=>a+totals(j).sell,0)):'Restricted'}</td></tr>`).join('')}</tbody></table></div></div><div class="card cardpad"><div class="cardtitle"><h3>Airlines, GSAs & vendors</h3><small>${vendors.length} records</small></div><div class="tablebox"><table class="table"><thead><tr><th>Name</th><th>Related jobs</th><th>Vendor bills</th></tr></thead><tbody>${vendors.map(v=>`<tr><td class="strong">${esc(v)}</td><td>${state.jobs.filter(j=>j.airline===v).length}</td><td>${state.payables.filter(p=>p.vendor===v).length}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function settings(){return `${head('Settings & Audit','Configure billing defaults, access roles, branch scope, reminders and data ownership.',`<button class="btn" onclick="exportAll()">⇩ Export full demo data</button><button class="btn danger" onclick="confirmReset()">Reset sample data</button>`)}<div class="grid two"><div class="card cardpad"><div class="cardtitle"><h3>Company & invoicing configuration</h3></div><div class="formgrid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field('Company name','s_company',state.settings.company)}${field('Company email','s_email',state.settings.email)}${field('GSTIN','s_gstin',state.settings.gstin)}${field('PAN','s_pan',state.settings.pan)}${field('Bank account display','s_bank',state.settings.bank,'text',{w:'w2'})}${field('Company billing address','s_address',state.settings.address,'text',{w:'w2'})}${select('Default branch','s_branch',state.settings.branch,['Delhi (DEL)','Mumbai (BOM)','Bengaluru (BLR)','Hyderabad (HYD)'])}</div><div class="formactions"><button class="btn primary" onclick="saveSettings()">Save settings</button></div></div><div class="card cardpad"><div class="cardtitle"><h3>Payment reminders</h3></div><div class="formgrid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${field('Days before due date','s_remindBefore',state.settings.remindBefore,'number')}${field('Repeat interval after due','s_remindAfter',state.settings.remindAfter,'number')}</div><div class="note" style="margin-top:17px">Automatic emails, background scheduling, PDF delivery and recurring jobs are not running in the browser prototype. These settings define a proposed production workflow.</div><div class="divider"></div><div class="cardtitle"><h3>Role access preview</h3></div><table class="table"><thead><tr><th>Role</th><th>Jobs / documents</th><th>Finance</th><th>Profit sharing</th></tr></thead><tbody>${['Management','Sales','Operations','Documentation','Finance'].map(r=>`<tr><td>${r}</td><td>${['Management','Sales','Operations','Documentation'].includes(r)?'Allowed':'Restricted'}</td><td>${['Management','Finance'].includes(r)?'Allowed':'Restricted'}</td><td>${r==='Management'?'Allowed':'Restricted'}</td></tr>`).join('')}</tbody></table></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Activity audit trail</h3><small>Local demonstration event log</small></div><div class="tablebox"><table class="table"><thead><tr><th>Timestamp</th><th>Performed by</th><th>Module</th><th>Action</th></tr></thead><tbody>${state.audit.slice(0,40).map(a=>`<tr><td>${esc(a.date)}</td><td>${esc(a.user)}</td><td>${esc(a.module)}</td><td>${esc(a.action)}</td></tr>`).join('')}</tbody></table></div></div><div class="note section">Production requirements: server-side authentication and RBAC, encryption, immutable financial audit logs, data retention policy, backup/restore, reliable file storage, tenant/branch permissions, approval rules and secure customer data export.</div>`}
function saveSettings(){for(const k of ['company','email','gstin','pan','bank','address','branch','remindBefore','remindAfter']){const x=$('[name=s_'+k+']');if(x)state.settings[k]=k.startsWith('remind')?Math.max(1,+x.value||1):x.value}audit('Updated system and billing preferences','Settings');render();toast('Settings saved locally.')}
function exportAll(){downloadText(JSON.stringify({...state,documents:state.documents.map(({blobKey,...d})=>({...d,blobKey:'LOCAL_BROWSER_ONLY'}))},null,2),'airbridge-demo-data.json','application/json');toast('Records exported; document file blobs require individual download.')}
function confirmReset(){if(!confirm('Reset ALL local demo changes and sample records? This cannot be undone.'))return;state=seed();save();navigate('dashboard');toast('Sample records reset. Stored document blobs may remain in browser storage.')}
function csv(kind){let rows=[];if(kind==='jobs')rows=[['Job ID','Customer','Shipper','Consignee','Origin','Destination','Airline','MAWB','HAWB','Flight','Status','Revenue INR','Costs INR','Profit INR','Margin %'],...state.jobs.map(j=>[j.id,j.customer,j.shipper,j.consignee,j.origin,j.destination,j.airline,j.mawb,j.hawb,j.flight,j.status,canFinance()?totals(j).sell:'Restricted',canFinance()?totals(j).cost:'Restricted',canProfit()?totals(j).profit:'Restricted',canProfit()?totals(j).margin.toFixed(2):'Restricted'])];if(kind==='invoices')rows=[['Invoice','Type','Customer','Job','Date','Due','Total','Paid','Outstanding','Status'],...state.invoices.map(i=>[i.id,i.type,i.customer,i.jobId,i.date,i.due,invTotal(i).total,i.paid,invTotal(i).balance,i.status])];if(kind==='payables')rows=[['Bill','Vendor','Job','Cost Head','Amount','Paid','Outstanding','Due'],...state.payables.map(x=>[x.id,x.vendor,x.jobId,x.head,x.amount,x.paid,x.amount-x.paid,x.due])];if(kind==='report')rows=[[ui.reportGroup,'Shipments','Revenue INR','Cost INR','Profit INR','Margin %'],...reportRows().map(x=>[x.name,x.count,canFinance()?x.revenue:'Restricted',canFinance()?x.cost:'Restricted',canProfit()?x.profit:'Restricted',canProfit()&&x.revenue?(x.profit/x.revenue*100).toFixed(2):'Restricted'])];if(kind==='journal')rows=[['Posting date','Document','Description','Account','Debit INR','Credit INR'],...journalEntries().map(x=>[x.date,x.ref,x.description,x.account,x.debit,x.credit])];if(kind==='shares'){rows=[['Job ID','Lane','Person','Ratio %','Amount INR'],...state.jobs.flatMap(j=>(activeShare(j)?.parts||[]).map(p=>[j.id,j.lane,p.name,p.pct,Math.max(0,totals(j).profit)*p.pct/100]))]}downloadText(rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),'airbridge-'+kind+'.csv','text/csv;charset=utf-8')}
function downloadText(str,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([str],{type}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportReminderCalendar(){const rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AirBridge Demo//EN'];for(const t of state.tasks){rows.push('BEGIN:VEVENT','UID:'+t.id+'@airbridge-demo','DTSTART;VALUE=DATE:'+t.due.replaceAll('-',''),'DTEND;VALUE=DATE:'+t.due.replaceAll('-',''),'SUMMARY:'+t.title.replace(/[,;]/g,' '),'DESCRIPTION:'+t.notes.replace(/[\n,;]/g,' '),'END:VEVENT')}rows.push('END:VCALENDAR');downloadText(rows.join('\r\n'),'airbridge-followups.ics','text/calendar')}
function openModal(type,ref=''){ui.modal=type+(ref?'|'+ref:'');render()}
function modal(){let raw=ui.modal,kind=raw.split('|')[0],ref=raw.split('|')[1]||'',inner='',title='';
if(kind==='booking'){title='Add flight booking';inner=`<form id="modalForm" onsubmit="addBooking(event)"><div class="formgrid">${select('Linked job','m_job',ref||state.jobs[0].id,state.jobs.map(x=>x.id))}${field('Flight number','m_flight','EY-223','text',{req:true})}${field('Origin IATA','m_origin',state.jobs.find(x=>x.id===(ref||state.jobs[0].id))?.origin||'DEL')}${field('Destination IATA','m_dest','AUH')}${field('Departure date','m_date',TODAY,'date')}${select('Space / allotment','m_allotment','General',['General','BSA','Hard block','Soft block','Ad-hoc'])}${field('Pieces','m_pcs',1,'number')}${field('Chargeable kg','m_weight',0,'number')}</div><div class="formactions"><button class="btn primary">Save booking request</button></div></form><p class="muted smalltxt">This records an internal booking request, not a confirmed reservation with the airline.</p>`}
else if(kind==='upload'){title='Upload shipment documentation';inner=`<div class="formgrid">${select('Related job','m_job',state.jobs[0].id,state.jobs.map(x=>x.id))}${select('Document type','documentType','MAWB Copy',DOC_TYPES)}</div><label class="docdrop" style="display:block;margin-top:16px" for="modalFiles"><strong>⇧ Choose documents</strong><span>Stored in this browser, not transmitted externally</span></label><input hidden multiple type="file" id="modalFiles" onchange="uploadDocs(event,$('[name=m_job]').value);ui.modal='';render()">`}
else if(kind==='quote'){title='Create customer quotation';inner=`<form id="modalForm" onsubmit="addQuote(event)"><div class="formgrid">${field('Customer','m_customer','', 'text',{req:true})}${field('Origin / Destination lane','m_lane','DEL–FRA','text',{req:true})}${field('Airline','m_airline','Etihad Cargo')}${field('Chargeable kg','m_chargeable',500,'number')}${field('Quoted selling amount','m_rate',0,'number',{req:true})}${select('Currency','m_currency','INR',['INR','USD','AED','EUR'])}${field('Valid until','m_valid','2026-11-30','date')}${select('Approval status','m_status','Pending Approval',['Pending Approval','Draft','Approved'])}</div><div class="formactions"><button class="btn primary">Save quotation</button></div></form>`}
else if(kind==='rate'){title='New airline tariff / ad-hoc rate';inner=`<form onsubmit="addRate(event)"><div class="formgrid">${field('Airline','m_airline','', 'text',{req:true})}${field('Lane','m_lane','DEL–FRA','text',{req:true})}${select('Rate type','m_type','Ad-hoc',['Ad-hoc','Contract','Spot','BSA'])}${select('Currency','m_currency','INR',['INR','USD','AED','EUR'])}${field('Minimum charge','m_min',0,'number')}${field('Charge per kg','m_perkg',0,'number')}${field('Valid to','m_valid','2026-12-31','date')}</div><div class="formactions"><button class="btn primary">Save rate</button></div></form>`}
else if(kind==='task'){title='Create a follow-up task';inner=`<form onsubmit="addTask(event)"><div class="formgrid">${field('Action / task title','m_title','', 'text',{req:true,w:'w2'})}${select('Related job','m_job','',['',...state.jobs.map(x=>x.id)])}${select('Related invoice','m_invoice','',['',...state.invoices.map(x=>x.id)])}${field('Customer','m_customer','')}${field('Due date','m_due',TODAY,'date',{req:true})}${select('Responsible team member','m_owner',TEAM[0],TEAM)}${select('Priority','m_priority','Normal',['Low','Normal','High','Urgent'])}${textArea('Notes','m_notes','',{w:'w2'})}</div><div class="formactions"><button class="btn primary">Create task</button></div></form>`}
else if(kind==='payable'){title='New vendor / airline bill';inner=`<form onsubmit="addPayable(event)"><div class="formgrid">${field('Vendor name','m_vendor','', 'text',{req:true})}${select('Linked shipment','m_job',state.jobs[0].id,state.jobs.map(x=>x.id))}${select('Cost head','m_head',COST_HEADS[0],COST_HEADS)}${field('Bill amount (INR)','m_amount',0,'number',{req:true})}${field('Due date','m_due','2026-11-15','date')}${field('Paid already (INR)','m_paid',0,'number')}</div><div class="formactions"><button class="btn primary">Save vendor bill</button></div></form>`}
else if(kind==='sea'){title='Register sea freight / bill of lading';inner=`<form onsubmit="addSea(event)"><div class="formgrid">${select('Sea freight job','m_job',state.jobs.find(j=>j.service.startsWith('Sea'))?.id||state.jobs[0].id,state.jobs.map(j=>j.id))}${field('Vessel name','m_vessel','','text',{req:true})}${field('Voyage','m_voyage','')}${field('Container number','m_container','')}${field('Master B/L (MBL)','m_mbl','')}${field('House B/L (HBL)','m_hbl','')}${field('Port of loading','m_pol','INNSA')}${field('Port of discharge','m_pod','DEHAM')}${field('ETD','m_etd',TODAY,'date')}${field('ETA','m_eta','2026-12-01','date')}${select('Movement','m_mode','FCL',['FCL','LCL','Breakbulk'])}</div><div class="formactions"><button class="btn primary">Save sea shipment details</button></div></form>`}
else if(kind==='cheque'){title='Record cheque / bank instrument';inner=`<form onsubmit="addCheque(event)"><div class="formgrid">${field('Cheque number','m_number','','text',{req:true})}${field('Bank','m_bank','Demo Bank')}${select('Direction','m_direction','Receivable',['Receivable','Payable'])}${field('Linked document number','m_ref','')}${field('Amount (INR)','m_amount',0,'number',{req:true})}${field('Cheque date','m_date',TODAY,'date')}${select('Status','m_status','Issued',['Issued','Deposited','Cleared','Bounced','Cancelled'])}</div><div class="formactions"><button class="btn primary">Save bank instrument</button></div></form>`}
else if(kind==='stock'){title='Add carrier AWB stock range';inner=`<form onsubmit="addStock(event)"><div class="formgrid">${field('Airline','m_airline','', 'text',{req:true})}${field('Airway bill prefix','m_prefix','', 'text',{req:true})}${field('Station','m_station','DEL')}${field('From serial','m_from','', 'number',{req:true})}${field('To serial','m_to','', 'number',{req:true})}</div><div class="formactions"><button class="btn primary">Create AWB stock range</button></div></form>`}
else if(kind==='share'){title='Configure authorised profit sharing';let s=ui.shareDraft;inner=`<div class="formgrid">${field('Lane / project name','share_lane',s.lane)}${select('Scope: individual shipment override','share_job',s.jobId,['',...state.jobs.map(j=>j.id)])}</div><div class="subhead" style="margin-top:20px">People and percentage split <button class="btn small" onclick="ui.shareDraft.parts.push({name:'${TEAM[0]}',pct:0});$('#shareRows').innerHTML=shareRows();shareTotal()">＋ Add participant</button></div><div id="shareRows">${shareRows()}</div><div class="sidepanel" style="margin-top:15px"><strong id="shareTotal">${s.parts.reduce((a,p)=>a+p.pct,0)}% allocated · ${100-s.parts.reduce((a,p)=>a+p.pct,0)}% company retained</strong><p class="muted smalltxt">Enter up to 100%. Unallocated profit remains with the company. Management approval is required in production.</p></div><div class="formactions"><button class="btn primary" onclick="saveShare()">Save distribution</button></div>`}
else if(kind==='party'){title='Add customer or vendor';inner=`<form onsubmit="addParty(event)"><div class="formgrid">${field('Company / party name','m_name','', 'text',{req:true})}${select('Party category','m_type','Customer',['Customer','Vendor'])}${field('Contact email','m_email','')}${field('GSTIN (if applicable)','m_gstin','')}${field('Phone','m_phone','')}${field('Office address','m_address','')}</div><div class="formactions"><button class="btn primary">Save party</button></div></form>`}
else if(kind==='quotejob'){let q=state.quotes.find(x=>x.id===kind.slice(9)||x.id===raw.split(':')[1]);title='Convert quotation to shipment';inner='<p>Loading quotation…</p>'}
else if(raw.startsWith('payment:')||raw.startsWith('vendorpay:')){let [key,k]=raw.split(':');const inv=key==='payment'?state.invoices.find(x=>x.id===k):state.payables.find(x=>x.id===k);title=key==='payment'?'Record customer payment':'Record vendor settlement';let due=key==='payment'?invTotal(inv).balance:Math.max(0,inv.amount-inv.paid);inner=`<form onsubmit="submitPayment(event,'${key}','${k}')"><div class="sidepanel">Document: <strong>${k}</strong> · Outstanding: <strong>${money(due)}</strong></div><div class="formgrid" style="margin-top:16px">${field('Amount received / paid (INR)','m_amount',due,'number',{req:true,extra:'min="0.01" step="0.01" max="'+due+'"'})}${field('Payment date','m_date',TODAY,'date')}${select('Method','m_method','Bank transfer',['Bank transfer','Cash','UPI','Cheque','Other'])}${field('Transaction reference','m_reference','')}</div><div class="formactions"><button class="btn primary">Record payment</button></div></form>`}
else if(raw.startsWith('allocate:')){let [k,sid,awb]=raw.split(':'),s=state.awbstock.find(x=>x.id===sid);title='Allocate MAWB number';inner=`<form onsubmit="submitAllocation(event,'${sid}','${awb}')"><div class="sidepanel">Available AWB: <strong>${s.prefix}-${awb}</strong><br>Airline: ${esc(s.airline)}</div><div class="formgrid" style="margin-top:16px">${select('Assign to shipment','m_job',state.jobs.find(j=>!j.mawb)?.id||state.jobs[0].id,state.jobs.map(j=>j.id))}</div><div class="formactions"><button class="btn primary">Allocate MAWB to job</button></div></form>`}
else if(raw.startsWith('quotejob:')){let q=state.quotes.find(x=>x.id===raw.split(':')[1]);title='Convert quotation to job';inner=`<p>Convert approved quotation <strong>${esc(q?.id)}</strong> for <strong>${esc(q?.customer)}</strong> into a linked shipment draft?</p><div class="formactions"><button class="btn primary" onclick="convertQuote('${q?.id}')">Create linked shipment</button></div>`}
return `<div class="modal-wrap" onclick="if(event.target===this){ui.modal='';render()}"><div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>${title||'Action'}</h2><button class="btn ghost" aria-label="Close" onclick="ui.modal='';render()">✕</button></div>${inner}</div></div>`}
function mv(n){return document.getElementsByName('m_'+n)[0]?.value||''}
function doneModal(message,activity='',module='General'){if(activity)audit(activity,module);ui.modal='';save();render();toast(message)}
function addBooking(e){e.preventDefault();const j=state.jobs.find(x=>x.id===mv('job'));state.bookings.unshift({id:'BK-26-'+String(43+state.bookings.length).padStart(3,'0'),jobId:j.id,flight:mv('flight'),date:mv('date'),origin:mv('origin').toUpperCase(),dest:mv('dest').toUpperCase(),allotment:mv('allotment'),pcs:+mv('pcs'),weight:+mv('weight'),status:'Requested'});doneModal('Booking request recorded locally.','Created booking for '+j.id,'Bookings')}
function addQuote(e){e.preventDefault();state.quotes.unshift({id:'QT-2026-'+String(33+state.quotes.length).padStart(3,'0'),customer:mv('customer'),lane:mv('lane'),currency:mv('currency'),rate:+mv('rate'),chargeable:+mv('chargeable'),valid:mv('valid'),status:mv('status'),jobId:'',airline:mv('airline')});doneModal('Quotation created.','Created quotation for '+mv('customer'),'Sales')}
function addRate(e){e.preventDefault();state.tariffs.unshift({id:'RATE-'+Date.now(),airline:mv('airline'),lane:mv('lane'),type:mv('type'),currency:mv('currency'),min:+mv('min'),perkg:+mv('perkg'),valid:mv('valid')});doneModal('Airline rate stored locally.','Added airline rate '+mv('lane'),'Sales')}
function addTask(e){e.preventDefault();let inv=state.invoices.find(x=>x.id===mv('invoice')),job=state.jobs.find(x=>x.id===mv('job'));state.tasks.unshift({id:'TASK-'+Date.now(),title:mv('title'),invoice:mv('invoice'),jobId:mv('job'),customer:mv('customer')||inv?.customer||job?.customer||'',due:mv('due'),owner:mv('owner'),priority:mv('priority'),notes:mv('notes'),done:false});doneModal('Follow-up task created.','Assigned task to '+mv('owner'),'Tasks')}
function addPayable(e){e.preventDefault();state.payables.unshift({id:'BILL-'+String(24+state.payables.length).padStart(4,'0'),vendor:mv('vendor'),jobId:mv('job'),head:mv('head'),amount:+mv('amount'),paid:+mv('paid'),due:mv('due'),currency:'INR'});doneModal('Vendor bill added.','Added payable to '+mv('vendor'),'Finance')}
function addStock(e){e.preventDefault();let f=+mv('from'),t=+mv('to');if(t<f||t-f>99999){toast('Check the serial range (maximum 100,000 entries).');return}state.awbstock.push({id:'STK-'+Date.now(),prefix:mv('prefix'),airline:mv('airline'),station:mv('station'),from:f,to:t,used:[],status:'Active'});doneModal('AWB stock range created.','Added AWB stock '+mv('prefix'),'Stock')}
function addParty(e){e.preventDefault();state.parties=state.parties||[];state.parties.push({name:mv('name'),type:mv('type'),email:mv('email'),gstin:mv('gstin'),phone:mv('phone'),address:mv('address')});doneModal('Party added to master records.','Added '+mv('type')+' '+mv('name'),'Masters')}
function submitPayment(e,key,k){e.preventDefault();const v=+mv('amount');const target=key==='payment'?state.invoices.find(x=>x.id===k):state.payables.find(x=>x.id===k);const due=key==='payment'?invTotal(target).balance:Math.max(0,target.amount-target.paid);if(v<=0||v>due+0.01){toast('Payment must be positive and cannot exceed the outstanding balance.');return}target.paid=+(+target.paid+v).toFixed(2);state.payments.unshift({id:'PAY-'+Date.now(),date:mv('date'),ref:k,type:key==='payment'?'Customer receipt':'Vendor payment',method:mv('method'),reference:mv('reference'),amount:v});if(key==='payment'){target.status=invTotal(target).balance<0.01?'Paid':'Part Paid'}doneModal('Payment recorded. Outstanding balance updated.','Recorded '+money(v)+' against '+k,'Finance')}
function submitAllocation(e,sid,awb){e.preventDefault();const s=state.awbstock.find(x=>x.id===sid),j=state.jobs.find(x=>x.id===mv('job'));if(j.mawb&&!confirm('This shipment already has MAWB '+j.mawb+'. Replace it?'))return;s.used.push(+awb);j.mawb=s.prefix+'-'+awb;doneModal('MAWB allocated to job '+j.id+'.','Allocated MAWB '+j.mawb,'Stock')}
function convertQuote(qid){const q=state.quotes.find(x=>x.id===qid);if(!q||q.status!=='Approved')return;let lane=q.lane.replace(/–/g,'-').split('-'),jid=`JOB-2026-${String(188+state.jobs.length).padStart(4,'0')}`,j={id:jid,customer:q.customer,shipper:q.customer,consignee:'',origin:lane[0]?.trim()||'DEL',destination:lane[1]?.trim()||'FRA',airline:q.airline,agent:'Direct',mawb:'',hawb:'',flight:'',date:TODAY,commodity:'To be entered',pieces:1,gross:q.chargeable,volume:0,chargeable:q.chargeable,currency:q.currency,fx:state.settings.fx[q.currency]||1,sell:q.rate,costs:Array(8).fill(0),status:'Draft',owner:TEAM[0],branch:state.settings.branch,lane:q.lane,notes:'Converted from quotation '+qid,screening:'Pending',allotment:'General',service:'Air Export',created:TODAY};state.jobs.unshift(j);q.jobId=jid;audit('Converted quotation '+qid+' to job '+jid,'Sales');ui.modal='';openJob(jid);toast('Quotation converted to editable job draft.')}
function go(p){ui.filter='';ui.status='All';navigate(p)}

function sea(){return `${head('Sea Freight Documentation','Reference workflow for D-Solution sea freight documents, linked to the same customer and job database.',`<button class="btn" onclick="go('documents')">Document centre</button><button class="btn primary" onclick="openModal('sea')">＋ Add sea freight record</button>`)}<div class="grid three"><div class="metric"><div class="mlabel">Sea records</div><div class="mval">${state.seaBookings.length}</div></div><div class="metric"><div class="mlabel">FCL movements</div><div class="mval">${state.seaBookings.filter(s=>s.mode==='FCL').length}</div></div><div class="metric"><div class="mlabel">LCL movements</div><div class="mval">${state.seaBookings.filter(s=>s.mode==='LCL').length}</div></div></div><div class="card cardpad section"><div class="cardtitle"><h3>Ocean freight and bill-of-lading register</h3><small>MBL / HBL, vessel, voyage, containers, departure and arrival</small></div><div class="tablebox"><table class="table"><thead><tr><th>Job</th><th>MBL / HBL</th><th>Vessel</th><th>Container</th><th>Loading → Discharge</th><th>ETD / ETA</th><th>Mode</th><th>Documents</th></tr></thead><tbody>${state.seaBookings.map(s=>`<tr><td><button class="linkbutton" onclick="openJob('${s.jobId}','docs')">${s.jobId}</button></td><td>${esc(s.mbl||'—')}<br><small>${esc(s.hbl||'—')}</small></td><td>${esc(s.vessel)}<br><small>${esc(s.voyage)}</small></td><td>${esc(s.container||'—')}</td><td>${esc(s.pol)} → ${esc(s.pod)}</td><td>${fmtDate(s.etd)}<br><small>${fmtDate(s.eta)}</small></td><td>${badge(s.mode)}</td><td><button class="btn small" onclick="openJob('${s.jobId}','docs')">Upload B/L</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No sea-freight movements recorded. Create a Sea Export/Import job, then register the vessel, MBL, HBL and container details.</td></tr>'}</tbody></table></div></div><div class="note section">Sea freight documentation is included as an adjacent D-Solution reference. Carrier EDI, container tracking, customs submissions and live vessel schedules are outside this disconnected prototype.</div>`}
function addSea(e){e.preventDefault();let x={id:'SEA-'+Date.now(),jobId:mv('job'),vessel:mv('vessel'),voyage:mv('voyage'),container:mv('container'),mbl:mv('mbl'),hbl:mv('hbl'),pol:mv('pol'),pod:mv('pod'),etd:mv('etd'),eta:mv('eta'),mode:mv('mode')};state.seaBookings.unshift(x);doneModal('Sea freight movement saved.','Added ocean movement for '+x.jobId,'Sea freight')}
function addCheque(e){e.preventDefault();state.cheques.unshift({id:'CHQ-'+Date.now(),number:mv('number'),bank:mv('bank'),direction:mv('direction'),ref:mv('ref'),amount:+mv('amount'),date:mv('date'),status:mv('status')});doneModal('Cheque / bank instrument saved.','Added bank instrument '+mv('number'),'Bank')}
function chequeStatus(k){const c=state.cheques.find(x=>x.id===k);if(c){c.status=c.status==='Cleared'?'Issued':'Cleared';audit('Updated cheque status '+k+' → '+c.status,'Bank');render()}}
function journalEntries(){let rows=[];const add=(date,ref,description,account,debit,credit)=>rows.push({date,ref,description,account,debit,credit});for(const i of state.invoices){if(i.type!=='Tax Invoice')continue;const t=invTotal(i);add(i.date,i.id,'Customer invoice — '+i.customer,'Accounts Receivable',t.total,0);add(i.date,i.id,'Recognised freight services','Freight Revenue',0,t.sub);if(t.gst)add(i.date,i.id,'Illustrative output tax','GST Output (illustrative)',0,t.gst)}for(const p of state.payables){add(p.due,p.id,'Vendor charge — '+p.vendor,p.head,p.amount,0);add(p.due,p.id,'Payable to '+p.vendor,'Accounts Payable',0,p.amount)}for(const x of state.payments){if(x.type==='Customer receipt'){add(x.date,x.ref,'Incoming '+x.method,'Bank / Cash',x.amount,0);add(x.date,x.ref,'Customer payment','Accounts Receivable',0,x.amount)}else{add(x.date,x.ref,'Vendor settlement','Accounts Payable',x.amount,0);add(x.date,x.ref,'Outgoing '+x.method,'Bank / Cash',0,x.amount)}}return rows.sort((a,b)=>b.date.localeCompare(a.date))}
function ledger(){if(!canFinance())return noAccess();let tabs=['General ledger','Bank & cheque control','Overseas / FX accounts'];return `${head('Ledger & Bank','A consolidated accounting workspace based on shipment invoices, vendor bills and recorded settlements.',`<button class="btn" onclick="csv('journal')">⇩ Export journal</button><button class="btn primary" onclick="openModal('cheque')">＋ Record cheque</button>`)}<div class="card cardpad"><div class="tabs">${tabs.map(t=>`<button class="tab ${ui.ledgerTab===t?'active':''}" onclick="ui.ledgerTab='${t}';render()">${t}</button>`).join('')}</div>${ui.ledgerTab==='General ledger'?`<div class="note">Illustrative double-entry postings derived from saved invoices, payables and payments. This is not a posted, reconciled general ledger; debit/credit notes, opening balances, tax posting policies and bank reconciliation require production configuration.</div><div class="tablebox section"><table class="table"><thead><tr><th>Posting date</th><th>Document</th><th>Description</th><th>Ledger account</th><th>Debit (INR)</th><th>Credit (INR)</th></tr></thead><tbody>${journalEntries().map(r=>`<tr><td>${fmtDate(r.date)}</td><td class="strong">${esc(r.ref)}</td><td>${esc(r.description)}</td><td>${esc(r.account)}</td><td>${r.debit?money(r.debit):'—'}</td><td>${r.credit?money(r.credit):'—'}</td></tr>`).join('')}</tbody></table></div>`:ui.ledgerTab==='Bank & cheque control'?`<div class="subhead">Recorded bank / cash payments</div><div class="tablebox"><table class="table"><thead><tr><th>Date</th><th>Document</th><th>Type</th><th>Method</th><th>Transaction reference</th><th>Amount</th></tr></thead><tbody>${state.payments.map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${esc(x.ref)}</td><td>${esc(x.type)}</td><td>${esc(x.method)}</td><td>${esc(x.reference)}</td><td>${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No individual payment transactions yet. Record a customer or vendor payment.</td></tr>'}</tbody></table></div><div class="subhead" style="margin-top:24px">Cheque and bank instruments</div><div class="tablebox"><table class="table"><thead><tr><th>Cheque</th><th>Bank</th><th>Direction</th><th>Linked document</th><th>Amount</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody>${state.cheques.map(c=>`<tr><td>${esc(c.number)}</td><td>${esc(c.bank)}</td><td>${esc(c.direction)}</td><td>${esc(c.ref)}</td><td>${money(c.amount)}</td><td>${fmtDate(c.date)}</td><td>${badge(c.status)}</td><td><button class="btn small" onclick="chequeStatus('${c.id}')">Toggle cleared</button></td></tr>`).join('')||'<tr><td colspan="8" class="muted">No cheques registered.</td></tr>'}</tbody></table></div>`:`<div class="subhead">Multi-currency shipment conversion</div><div class="tablebox"><table class="table"><thead><tr><th>Shipment</th><th>Customer</th><th>Currency</th><th>Selling in currency</th><th>INR FX rate</th><th>INR equivalent</th></tr></thead><tbody>${state.jobs.map(j=>`<tr><td><button class="linkbutton" onclick="openJob('${j.id}','costs')">${j.id}</button></td><td>${esc(j.customer)}</td><td>${j.currency}</td><td>${money(j.sell,j.currency)}</td><td>${j.fx}</td><td>${money(totals(j).sell)}</td></tr>`).join('')}</tbody></table></div><div class="note section">Exchange rates are user-entered and can be changed at shipment level. Currency gains/losses and overseas bank statement reconciliation are proposed production workflows, not live in this demo.</div>`}</div>`}

/* Reinitialise navigation from an untrusted file-open context without any external requests. */
render();
